# ══════════════════════════════════════════════════════════════════════════════
#  Loading Animation
# ══════════════════════════════════════════════════════════════════════════════
class LoadingDialog(QDialog):
    """Dialog loading sederhana dengan animasi titik-titik"""
    def __init__(self, message="Loading...", parent=None):
        super().__init__(parent)

        self.setWindowFlags(Qt.WindowType.FramelessWindowHint | Qt.WindowType.Dialog)
        self.setModal(True)
        self.setMinimumSize(300, 100)
        self.setStyleSheet("background: #2d2d2d; border: 1px solid #5a8a2e; border-radius: 10px;")
        layout = QVBoxLayout(self)
        layout.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.label = QLabel(message)
        self.label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.label.setStyleSheet("color: #e8e8e8; font-size: 14px;")
        layout.addWidget(self.label)

        self.dot_count = 0
        self.timer = QTimer()
        self.timer.timeout.connect(self._animate)
        self.timer.start(500)

    def _animate(self):
        self.dot_count = (self.dot_count + 1) % 4
        dots = "." * self.dot_count
        base_text = self.label.text().split(".")[0]
        self.label.setText(f"{base_text}{dots}")

    def closeEvent(self, e):
        self.timer.stop()
        super().closeEvent(e)


def save_session(user_id, username):
    """Simpan session 'Remember Me' memakai TOKEN ACAK (bukan password_hash).

    File di disk hanya berisi token sekali pakai yang:
      - diverifikasi terhadap hash-nya di database,
      - punya masa berlaku (db.SESSION_TOKEN_DAYS hari),
      - hangus saat logout / ganti password / akun di-lock.
    """
    try:
        token = db.create_session_token(user_id)
        data = {
            "user_id": user_id,
            "username": username,
            "token": token,
            "timestamp": datetime.now().isoformat()
        }
        # Tulis ke file sementara lalu rename untuk atomic operation
        temp_file = SESSION_FILE + ".tmp"
        with open(temp_file, "w") as f:
            json.dump(data, f)
        os.replace(temp_file, SESSION_FILE)  # atomic di Windows
        try:
            os.chmod(SESSION_FILE, 0o600)   # hanya pemilik yang bisa baca (POSIX)
        except OSError:
            pass
    except Exception as e:
        log.error(f"Save session error: {e}")

def load_session():
    """Load session jika token valid & belum kedaluwarsa."""
    if not os.path.exists(SESSION_FILE):
        return None
    try:
        with open(SESSION_FILE, "r") as f:
            data = json.load(f)
        # Validasi struktur
        if not all(k in data for k in ("user_id", "username", "token")):
            clear_session()
            return None
        # Verifikasi token ke database (hash + expiry)
        if db.validate_session_token(data["user_id"], data["token"]):
            user = db.get_user(data["user_id"])
            if user:
                return {"user_id": data["user_id"], "username": data["username"]}
        # Session tidak valid, hapus file
        clear_session()
        return None
    except Exception as e:
        log.warning(f"Load session gagal: {e}")
        clear_session()
        return None

def clear_session():
    """Hapus file session DAN hanguskan token-nya di database."""
    try:
        if os.path.exists(SESSION_FILE):
            try:
                with open(SESSION_FILE, "r") as f:
                    data = json.load(f)
                if "user_id" in data and "token" in data:
                    db.delete_session_token(data["user_id"], data["token"])
            except Exception:
                pass
            os.remove(SESSION_FILE)
    except Exception as e:
        log.warning(f"Clear session error: {e}")
# ══════════════════════════════════════════════════════════════════════════════
#  APP STATE  ─ single source of truth, avoids restart-to-sync bugs
# ══════════════════════════════════════════════════════════════════════════════
class AppState:
    user_id: int = 0
    _lang: str = "en"
    _cbs: list = []
    _lang_cbs: list = []
    _refresh_timer = None
    _refresh_pending = False

    @classmethod
    def set_user(cls, uid: int):
        cls.user_id = uid
        t = db.get_user_theme(uid)
        apply_theme(t)
        SoundEngine.enabled = bool(db.get_user(uid).get("sound_enabled", 1))
        # Load language from DB
        cls._lang = db.get_user_language(uid)

    @classmethod
    def get_language(cls):
        return cls._lang

    @classmethod
    def set_language(cls, lang_code):
        if lang_code not in ("id", "en"):
            return
        cls._lang = lang_code
        if cls.user_id:
            db.set_user_language(cls.user_id, lang_code)
        # Trigger all language callbacks
        for cb in cls._lang_cbs:
            try:
                cb()
            except Exception:
                pass

    @classmethod
    def register_lang_cb(cls, cb):
        if cb not in cls._lang_cbs:
            cls._lang_cbs.append(cb)

    @classmethod
    def unregister_lang_cb(cls, cb):
        if cb in cls._lang_cbs:
            cls._lang_cbs.remove(cb)

    @classmethod
    def user(cls) -> dict:
        return db.get_user(cls.user_id) if cls.user_id else {}

    @classmethod
    def refresh(cls):
        """Jadwalkan refresh data secara coalesced (satu kali per event-loop tick).

        Sebelumnya: tiap panggilan refresh() langsung me-reload semua halaman
        (sampai 18 halaman) secara sinkron -> sumber delay/freeze saat banyak
        perubahan berturut-turut (mis. gain_xp_gold memanggil refresh() berkali).
        Sekarang: panggilan berulang dalam tick yang sama digabung jadi satu.
        """
        if cls._refresh_timer is None:
            try:
                cls._refresh_timer = QTimer()
                cls._refresh_timer.setSingleShot(True)
                cls._refresh_timer.setInterval(0)
                cls._refresh_timer.timeout.connect(cls._flush_refresh)
            except Exception:
                cls._refresh_timer = None
        if cls._refresh_timer is None:
            cls._flush_refresh()
            return
        if not cls._refresh_timer.isActive():
            cls._refresh_timer.start()

    @classmethod
    def _flush_refresh(cls):
        for cb in list(cls._cbs):
            try: cb()
            except Exception: pass

    @classmethod
    def register(cls, cb):
        if cb not in cls._cbs: cls._cbs.append(cb)

    @classmethod
    def unregister(cls, cb):
        if cb in cls._cbs: cls._cbs.remove(cb)

# ══════════════════════════════════════════════════════════════════════════════
#  SMALL HELPERS
# ══════════════════════════════════════════════════════════════════════════════
# Fungsi global untuk memudahkan akses terjemahan
def tr(key, **kwargs):
    """Get translated text for current user language."""
    lang = AppState.get_language()
    text = get_text(key, lang)
    if kwargs:
        return text.format(**kwargs)
    return text

def _lbl(text, obj="", size=13, bold=False):
    if size <= 0: size = 10
    size = max(6, round(size * _FONT_SCALE))
    w = QLabel(text)
    w.setFont(QFont("Segoe UI", size, QFont.Weight.Bold if bold else QFont.Weight.Normal))
    if obj: w.setObjectName(obj)
    return w

def _btn(text, obj="", slot=None, h=38):
    b = QPushButton(text)
    if obj:
        b.setObjectName(obj)
    if slot:
        b.clicked.connect(slot)
    b.setMinimumHeight(h)
    return b

from PyQt6.QtWidgets import QGraphicsDropShadowEffect

def _card() -> QFrame:
    f = QFrame()
    f.setObjectName("card")
    # Catatan: QGraphicsDropShadowEffect sengaja TIDAK dipakai per-kartu karena
    # sangat berat saat direbuild tiap load() (sumbu utama delay pindah tab).
    # Tampilan modern sudah diatur via QSS (#card: border-radius + border + bg glass).
    return f

# ── Skala ikon/emoji konsisten seluruh aplikasi (medium) ──
ICON_INLINE = 14   # ikon sejajar teks: navbar, chips, folder, tab, tombol, list
ICON_CARD   = 24   # ikon kartu: stat shop/pet/achievement/task/economy cards
ICON_HERO   = 30   # avatar, rank, boss & hero dialog


def _fmt_qty(v) -> str:
    """Format kuantitas: bilangan bulat tanpa desimal ('x1'), pecahan 1 desimal
    ('x0.5') — supaya tidak tampil 'x1.0'."""
    try:
        f = float(v)
    except (TypeError, ValueError):
        return str(v)
    return str(int(f)) if f.is_integer() else f"{f:.1f}"

def _emoji_label(text: str, px: int = ICON_CARD) -> QLabel:
    """Render emoji ke pixmap di ukuran PASTI (px) memakai font 'Segoe UI Emoji'.
    Bebas dari quirk scaling emoji -> selalu tampil sebesar px di sistem apa pun.
    Ukuran dinormalisasi ke tier medium (ICON_INLINE / ICON_CARD / ICON_HERO)."""
    lbl = QLabel()
    size = px + 6
    pm = QPixmap(size, size)
    pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setRenderHint(QPainter.RenderHint.TextAntialiasing)
    f = QFont("Segoe UI Emoji"); f.setPixelSize(px)
    p.setFont(f)
    p.drawText(pm.rect(), Qt.AlignmentFlag.AlignCenter, text)
    p.end()
    lbl.setPixmap(pm)
    lbl.setFixedSize(size, size)
    return lbl

def _scrolled(inner):
    sa = QScrollArea()
    sa.setWidgetResizable(True)
    sa.setWidget(inner)
    sa.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
    return sa

def _sep():
    f = QFrame()
    f.setFrameShape(QFrame.Shape.HLine)
    f.setStyleSheet(f"color: {_T('border')};")
    return f

def _combo(items):
    cb = QComboBox()
    cb.setMinimumHeight(42)
    for text, data in items:
        cb.addItem(text, data)
    return cb

def _parse_positive_amount(text: str):
    """Parse jumlah uang (float > 0) dari input teks.

    Return float jika valid, None jika kosong/bukan angka/<=0.
    Dipakai semua dialog ekonomi agar validasi tidak duplikatif.
    """
    try:
        val = float((text or "").strip().replace(",", "."))
    except (ValueError, AttributeError):
        return None
    return val if val > 0 else None


def _input(placeholder="", password=False):
    f = QLineEdit()
    f.setPlaceholderText(placeholder)
    f.setMinimumHeight(42)
    if password: f.setEchoMode(QLineEdit.EchoMode.Password)
    return f

def _cloud_relationship_gone(error) -> bool:
    """True jika Supabase melaporkan baris relasi sudah tidak ada di server
    (mis. DB Supabase di-reset atau akun pasangan dihapus)."""
    text = str(error).lower()
    return ("invalid_relationship" in text or "p0001" in text
            or "not found" in text or "does not exist" in text)


def _queue_cloud_couple_end(user_id, relationship):
    """Best-effort akhiri Couple di cloud TIDAK memblokir alur offline-first.
    RPC dijalankan di background thread; bila gagal (selain relasi-hilang)
    di-queue untuk sync berikutnya."""
    cloud_id = relationship.get("cloud_id")
    if not cloud_id or not db.get_cloud_user_link(user_id):
        return

    def job():
        from cloud_service import get_cloud_service
        cloud = get_cloud_service()
        if cloud.authenticated or cloud.restore_session(user_id):
            cloud.end_couple_relationship(cloud_id)
            return True
        return False

    def on_done(_):
        pass

    def on_error(error):
        if _cloud_relationship_gone(error):
            return
        try:
            db.enqueue_sync(user_id, "couple_end", relationship.get("id") or 0, "end", {"cloud_id": cloud_id})
        except Exception as exc:
            log.warning(f"enqueue couple_end gagal: {exc}")

    run_in_thread(None, job, on_done=on_done, on_error=on_error)


# ══════════════════════════════════════════════════════════════════════════════
#  BACKGROUND TASK HELPER — jalankan callable di QThread (anti-freeze UI)
# ══════════════════════════════════════════════════════════════════════════════
_BG_THREADS = set()
_BG_CLEANUP_REGISTERED = False


class _ThreadedTask(QObject):
    """Jalankan satu callable di QThread; hasil/error dikirim balik ke UI thread."""
    succeeded = pyqtSignal(object)
    failed = pyqtSignal(str)

    def __init__(self, fn):
        super().__init__()
        self._fn = fn

    def run(self):
        try:
            self.succeeded.emit(self._fn())
        except Exception as exc:  # noqa: BLE001
            self.failed.emit(str(exc))


def _ensure_bg_cleanup():
    global _BG_CLEANUP_REGISTERED
    if _BG_CLEANUP_REGISTERED:
        return
    try:
        app = QApplication.instance()
        if app is not None:
            app.aboutToQuit.connect(_wait_bg_threads)
            _BG_CLEANUP_REGISTERED = True
    except Exception:
        pass


def _wait_bg_threads():
    for thread in list(_BG_THREADS):
        try:
            thread.quit()
            thread.wait(2500)
        except Exception:
            pass


def run_in_thread(parent, fn, on_done=None, on_error=None):
    """Jalankan fn() di background thread. on_done(result) / on_error(str)
    dijalankan di UI thread. Aman dipanggil berulang-ulang (anti-freeze)."""
    thread = QThread()
    worker = _ThreadedTask(fn)
    worker.moveToThread(thread)
    thread.started.connect(worker.run)
    if on_done is not None:
        worker.succeeded.connect(on_done)
    if on_error is not None:
        worker.failed.connect(on_error)
    thread.finished.connect(worker.deleteLater)
    thread.finished.connect(thread.deleteLater)
    thread.finished.connect(lambda t=thread: _BG_THREADS.discard(t))
    _BG_THREADS.add(thread)
    _ensure_bg_cleanup()
    thread.start()
    return thread


# ══════════════════════════════════════════════════════════════════════════════
#  AUTO-UPDATER — worker + dialog (Supabase-hosted releases)
# ══════════════════════════════════════════════════════════════════════════════
class _UpdateWorker(QObject):
    progress = pyqtSignal(int, int)   # done, total
    succeeded = pyqtSignal()
    failed = pyqtSignal(str)

    def __init__(self, info):
        super().__init__()
        self.info = info

    def run(self):
        import updater
        zip_path = updater.download_release(
            self.info,
            progress_cb=lambda done, total: self.progress.emit(done, total),
        )
        updater.apply_downloaded(zip_path, self.info.get("version", ""))
        self.succeeded.emit()


class _UpdateDialog(QDialog):
    """Dialog pembaruan: countdown otomatis, update sekarang, atau nanti."""

    def __init__(self, info, parent=None):
        super().__init__(parent)
        self.info = info
        self._count = 15
        self._applying = False
        self._thread = None
        self.setWindowTitle(tr("update_available_title"))
        self.setMinimumWidth(520)
        self.setStyleSheet(build_ss())
        lay = QVBoxLayout(self)
        lay.setContentsMargins(24, 22, 24, 22); lay.setSpacing(12)
        lay.addWidget(_lbl(tr("update_available", version=info.get("version", "")), "section", 15, True))

        notes = info.get("notes") or ""
        if notes:
            notes_card = _card()
            nl = QVBoxLayout(notes_card); nl.setContentsMargins(14, 12, 14, 12); nl.setSpacing(6)
            nl.addWidget(_lbl(tr("update_notes_label"), "sub", 10, True))
            notes_lbl = QLabel(notes)
            notes_lbl.setWordWrap(True)
            notes_lbl.setTextInteractionFlags(Qt.TextInteractionFlag.TextSelectableByMouse)
            nl.addWidget(notes_lbl)
            lay.addWidget(notes_card)

        self.status_lbl = _lbl(tr("update_auto_countdown", n=self._count), "sub", 11)
        self.status_lbl.setWordWrap(True)
        lay.addWidget(self.status_lbl)

        self.progress_bar = QProgressBar()
        self.progress_bar.setTextVisible(False)
        self.progress_bar.setRange(0, 100)
        self.progress_bar.setValue(0)
        self.progress_bar.hide()
        lay.addWidget(self.progress_bar)

        buttons = QHBoxLayout()
        buttons.addStretch()
        self.later_btn = _btn(tr("update_later"), "flat", self.accept)
        self.apply_btn = _btn(tr("update_apply"), "solid", self._start_apply, 38)
        buttons.addWidget(self.later_btn)
        buttons.addWidget(self.apply_btn)
        lay.addLayout(buttons)

        self._timer = QTimer(self)
        self._timer.timeout.connect(self._tick)
        self._timer.start(1000)

    def _tick(self):
        self._count -= 1
        if self._count <= 0:
            self._timer.stop()
            self._start_apply()
            return
        self.status_lbl.setText(tr("update_auto_countdown", n=self._count))

    def _start_apply(self):
        if self._applying:
            return
        self._applying = True
        self._timer.stop()
        self.apply_btn.setEnabled(False)
        self.later_btn.setEnabled(False)
        self.status_lbl.setText(tr("update_downloading", pct=0))
        self.progress_bar.show()

        thread = QThread(self)
        worker = _UpdateWorker(self.info)
        worker.moveToThread(thread)
        thread.started.connect(worker.run)
        worker.progress.connect(self._on_progress)
        worker.succeeded.connect(self._on_applied)
        worker.failed.connect(self._on_failed)
        worker.succeeded.connect(thread.quit)
        worker.failed.connect(thread.quit)
        thread.finished.connect(worker.deleteLater)
        thread.finished.connect(thread.deleteLater)
        self._thread = thread
        thread.start()

    def _on_progress(self, done, total):
        if total > 0:
            self.progress_bar.setValue(int(done * 100 / total))
            self.status_lbl.setText(tr("update_downloading", pct=int(done * 100 / total)))

    def _on_applied(self):
        self.status_lbl.setText(tr("update_restarting"))
        self.progress_bar.setValue(100)
        QTimer.singleShot(500, lambda: QApplication.instance().quit())

    def _on_failed(self, error):
        _show(self, tr("gagal_title"), tr("update_failed", error=error), "error")
        self.accept()

    def closeEvent(self, event):
        if self._applying:
            event.ignore()
            return
        super().closeEvent(event)


def _show(parent, title, msg, kind="info"):
    dlg = QDialog(parent)
    dlg.setWindowTitle(title)
    dlg.setMinimumWidth(380)
    dlg.setMinimumHeight(140)
    dlg.setStyleSheet(build_ss())
    lay = QVBoxLayout(dlg)
    lay.setContentsMargins(24,20,24,20)
    lay.setSpacing(14)
    icon = {"info":"💬","success":"✅","error":"❌","warning":"⚠️","levelup":"🎉"}.get(kind,"💬")
    lbl = QLabel(f"{icon}  {msg}")
    lbl.setWordWrap(True)
    lbl.setStyleSheet(f"color: {_T('text')}; font-size:13px;")
    lay.addWidget(lbl)
    ok = _btn(tr("msg_ok"), "solid", dlg.accept, 40)
    lay.addWidget(ok)
    dlg.exec()



