# Cache thumbnail galeri (photo_id -> QPixmap) agar tidak decode ulang tiap load.
_gallery_thumb_cache = {}


def _clear_gallery_thumb_cache(photo_id=None):
    if photo_id is None:
        _gallery_thumb_cache.clear()
    else:
        _gallery_thumb_cache.pop(photo_id, None)


def _rounded_photo_pixmap(image_data, size, circular=True):
    source = QPixmap()
    if not image_data or not source.loadFromData(bytes(image_data)):
        return QPixmap()
    source = source.scaled(size, size, Qt.AspectRatioMode.KeepAspectRatioByExpanding,
                           Qt.TransformationMode.SmoothTransformation)
    x = max(0, (source.width() - size) // 2); y = max(0, (source.height() - size) // 2)
    source = source.copy(x, y, size, size)
    output = QPixmap(size, size); output.fill(Qt.GlobalColor.transparent)
    painter = QPainter(output); painter.setRenderHint(QPainter.RenderHint.Antialiasing)
    path = QPainterPath()
    if circular:
        path.addEllipse(1, 1, size - 2, size - 2)
    else:
        path.addRoundedRect(1, 1, size - 2, size - 2, 12, 12)
    painter.setClipPath(path); painter.drawPixmap(0, 0, source); painter.end()
    return output


# Cache avatar pengguna (user_id,size,circular,updated_at) -> QPixmap ter-render.
# Menghindari decode+render ulang foto profil di list besar (friends/leaderboard/love).
_avatar_cache = {}


def _clear_avatar_cache(user_id=None):
    if user_id is None:
        _avatar_cache.clear()
    else:
        for key in list(_avatar_cache):
            if key[0] == user_id:
                _avatar_cache.pop(key, None)


def _set_user_photo(label, user, size=64, circular=True):
    user = user or {}
    uid = user.get("id")
    photo = db.get_profile_photo(uid) if uid else None
    updated = photo.get("updated_at") if photo else None
    cache_key = (uid, size, bool(circular), updated)
    pixmap = _avatar_cache.get(cache_key)
    if pixmap is None:
        pixmap = _rounded_photo_pixmap(photo.get("image_data") if photo else None, size, circular)
        if uid is not None:
            if len(_avatar_cache) > 400:  # batasi memori cache
                _avatar_cache.clear()
            _avatar_cache[cache_key] = pixmap
    label.setFixedSize(size, size); label.setAlignment(Qt.AlignmentFlag.AlignCenter)
    if not pixmap.isNull():
        label.setPixmap(pixmap); label.setText("")
        label.setStyleSheet(f"border:2px solid {_T('border')}; border-radius:{size//2 if circular else 12}px;")
    else:
        label.setPixmap(QPixmap()); label.setText(user.get("avatar_emoji", "⚔️"))
        label.setFont(QFont("Segoe UI Emoji", max(16, size // 2)))
        label.setStyleSheet(
            f"background:{user.get('avatar_color', _T('primary'))}; border:2px solid {_T('border')};"
            f" border-radius:{size//2 if circular else 12}px;")
    return label


def _user_photo_label(user, size=64, circular=True):
    return _set_user_photo(QLabel(), user, size, circular)


class _ImagePickerDialog(QDialog):
    """Native picker + decode/re-encode preview; raw paths are never persisted."""
    def __init__(self, title, parent=None, max_dimension=1280, circular_preview=False):
        super().__init__(parent)
        self.max_dimension = max_dimension; self.circular_preview = circular_preview
        self.image_data = None; self.mime_type = ""; self.image_width = 0; self.image_height = 0
        self.setWindowTitle(title); self.setMinimumWidth(500); self.setStyleSheet(build_ss())
        layout = QVBoxLayout(self); layout.setContentsMargins(22, 20, 22, 20); layout.setSpacing(12)
        self.preview = QLabel(tr("photo_no_selection")); self.preview.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.preview.setMinimumHeight(260); self.preview.setStyleSheet(
            f"background:{_T('bg')}; border:1px dashed {_T('border')}; border-radius:12px; color:{_T('muted')};")
        layout.addWidget(self.preview)
        self.info = _lbl(tr("photo_requirements"), "sub", 10); self.info.setWordWrap(True); layout.addWidget(self.info)
        row = QHBoxLayout(); self.browse_btn = _btn(tr("photo_browse"), "solid", self._browse, 36)
        row.addWidget(self.browse_btn); row.addStretch()
        self.buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel)
        self.buttons.button(QDialogButtonBox.StandardButton.Save).setEnabled(False)
        self.buttons.accepted.connect(self.accept); self.buttons.rejected.connect(self.reject); row.addWidget(self.buttons)
        layout.addLayout(row)

    def set_multi_mode(self, count):
        """Picker dinonaktifkan; metadata (caption/tanggal/visibility) dipakai semua file."""
        self.browse_btn.setEnabled(False)
        self.preview.setMinimumHeight(90)
        self.preview.setText(tr("love_gallery_multi_selected", n=count))
        self.buttons.button(QDialogButtonBox.StandardButton.Save).setEnabled(True)

    def _browse(self):
        path, _ = QFileDialog.getOpenFileName(
            self, tr("photo_choose_file"), "", "Images (*.jpg *.jpeg *.png);;JPEG (*.jpg *.jpeg);;PNG (*.png)")
        if not path:
            return
        try:
            if os.path.getsize(path) > 8 * 1024 * 1024:
                raise ValueError(tr("photo_error_original_size"))
            reader = QImageReader(path); reader.setAutoTransform(True)
            if not reader.canRead():
                raise ValueError(tr("photo_error_decode"))
            original_size = reader.size()
            if (original_size.width() < 32 or original_size.height() < 32
                    or original_size.width() * original_size.height() > 40_000_000):
                raise ValueError(tr("photo_error_dimensions_ui"))
            image = reader.read()
            if image.isNull():
                raise ValueError(tr("photo_error_decode"))
            image = image.scaled(self.max_dimension, self.max_dimension,
                                 Qt.AspectRatioMode.KeepAspectRatio,
                                 Qt.TransformationMode.SmoothTransformation)
            buffer = QBuffer(); buffer.open(QIODevice.OpenModeFlag.WriteOnly)
            if not image.save(buffer, "JPEG", 88):
                raise ValueError(tr("photo_error_encode"))
            data = bytes(buffer.data()); buffer.close()
            if len(data) > db.LOVE_PHOTO_MAX_BYTES:
                raise ValueError(tr("photo_error_file_size"))
            self.image_data = data; self.mime_type = "image/jpeg"
            self.image_width = image.width(); self.image_height = image.height()
            pm = (_rounded_photo_pixmap(data, 230, True) if self.circular_preview
                  else QPixmap.fromImage(image).scaled(420, 260, Qt.AspectRatioMode.KeepAspectRatio,
                                                       Qt.TransformationMode.SmoothTransformation))
            self.preview.setPixmap(pm); self.preview.setText("")
            self.info.setText(tr("photo_ready", width=image.width(), height=image.height(), kb=max(1, len(data)//1024)))
            self.buttons.button(QDialogButtonBox.StandardButton.Save).setEnabled(True)
        except Exception as error:
            self.image_data = None; self.buttons.button(QDialogButtonBox.StandardButton.Save).setEnabled(False)
            _show(self, tr("gagal_title"), str(error), "error")

    def payload(self):
        return self.image_data, self.mime_type, self.image_width, self.image_height


class _GalleryViewerDialog(QDialog):
    """Penampil foto galeri dengan zoom in/out/reset."""

    def __init__(self, photo, parent=None):
        super().__init__(parent)
        self.setWindowTitle(photo.get("caption") or tr("love_gallery_title"))
        self.resize(900, 680); self.setStyleSheet(build_ss())
        self._src = QPixmap(); self._src.loadFromData(photo["image_data"])
        self._zoom = 1.0
        lay = QVBoxLayout(self)
        bar = QHBoxLayout()
        self._zoom_lbl = _lbl("100%", "sub", 11)
        zout = _btn("➖", "flat", h=32, slot=self.zoom_out); zout.setToolTip(tr("love_gallery_zoom_out_tip"))
        zin = _btn("➕", "flat", h=32, slot=self.zoom_in); zin.setToolTip(tr("love_gallery_zoom_in_tip"))
        zres = _btn("🔄", "flat", h=32, slot=self.zoom_reset); zres.setToolTip(tr("love_gallery_zoom_reset_tip"))
        bar.addWidget(zout); bar.addWidget(zin); bar.addWidget(zres); bar.addWidget(self._zoom_lbl); bar.addStretch()
        lay.addLayout(bar)
        self._scroll = QScrollArea(); self._scroll.setWidgetResizable(False); self._scroll.setFrameShape(QFrame.Shape.NoFrame)
        self._image = QLabel(); self._image.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self._image.setCursor(Qt.CursorShape.OpenHandCursor)
        self._drag_pos = None
        self._image.installEventFilter(self)
        self._scroll.setWidget(self._image); lay.addWidget(self._scroll, 1)
        info = _lbl(tr("love_gallery_meta", date=photo.get("photo_date") or "—",
                       uploader=photo.get("uploader_name") or "—"), "sub", 10)
        info.setAlignment(Qt.AlignmentFlag.AlignCenter); lay.addWidget(info)
        lay.addWidget(_btn(tr("btn_close"), "solid", self.accept, 34))
        self._apply()

    def zoom_in(self):
        self._zoom = min(4.0, self._zoom * 1.25); self._apply()

    def zoom_out(self):
        self._zoom = max(0.25, self._zoom / 1.25); self._apply()

    def zoom_reset(self):
        self._zoom = 1.0; self._apply()

    def showEvent(self, event):
        super().showEvent(event)
        QTimer.singleShot(0, self._apply)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._apply()

    def _apply(self):
        if self._src.isNull():
            self._image.setText(tr("love_gallery_empty")); return
        # Baseline aman: minimal 640px, mengikuti lebar viewport bila lebih besar.
        vp = (self._scroll.viewport().width() if self._scroll.viewport().width() > 100 else 0)
        base_w = max(640, min(1400, vp - 24)) if vp else 840
        base_h = max(420, int(base_w * 0.68))
        fit = self._src.scaled(base_w, base_h, Qt.AspectRatioMode.KeepAspectRatio,
                               Qt.TransformationMode.SmoothTransformation)
        w = max(40, int(fit.width() * self._zoom)); h = max(40, int(fit.height() * self._zoom))
        self._image.setPixmap(self._src.scaled(w, h, Qt.AspectRatioMode.KeepAspectRatio,
                                               Qt.TransformationMode.SmoothTransformation))
        self._image.resize(w, h)
        # Foto lebih kecil dari viewport → center; lebih besar → scroll.
        vp = self._scroll.viewport()
        if w <= vp.width() and h <= vp.height():
            self._image.setMinimumSize(vp.width(), vp.height())
        else:
            self._image.setMinimumSize(0, 0)
        self._zoom_lbl.setText(f"{int(self._zoom * 100)}%")

    def eventFilter(self, obj, ev):
        """Pan foto dengan drag (hand cursor) saat di-zoom."""
        if obj is self._image:
            if ev.type() == QEvent.Type.MouseButtonPress and ev.button() == Qt.MouseButton.LeftButton:
                self._drag_pos = ev.position().toPoint()
                self._image.setCursor(Qt.CursorShape.ClosedHandCursor)
                return True
            if ev.type() == QEvent.Type.MouseButtonRelease:
                self._drag_pos = None
                self._image.setCursor(Qt.CursorShape.OpenHandCursor)
                return True
            if ev.type() == QEvent.Type.MouseMove and self._drag_pos is not None:
                delta = ev.position().toPoint() - self._drag_pos
                hs = self._scroll.horizontalScrollBar(); vs = self._scroll.verticalScrollBar()
                hs.setValue(hs.value() - delta.x()); vs.setValue(vs.value() - delta.y())
                return True
        return super().eventFilter(obj, ev)


