class NavBar(QWidget):
    tab_changed = pyqtSignal(str)

    ICON_MAP = {
        "dashboard": "🏠", "profile": "🎭", "habits": "⛏", "dailies": "📅",
        "todos": "📜", "sport": "🏅", "economy": "💰", "health_food": "💚",
        "love": "💞", "learning": "📚", "pomodoro": "🍅", "notes": "📝",
        "reminders": "⏰", "calendar": "📅", "crafting": "🔨", "shop": "🏪",
        "pets": "🐾", "friends": "👥", "guild": "⚔️", "achievements": "🏆",
        "leaderboard": "🎖️", "settings": "⚙️",
        # Auxiliary page available through the command palette.
        "music": "🎵",
        "supplies": "📦",
    }

    # Primary navigation order is product-wide and intentionally explicit.
    _TABS = [
        ("nav_home",         "dashboard"),
        ("nav_profile",      "profile"),
        ("nav_habits",       "habits"),
        ("nav_dailies",      "dailies"),
        ("nav_quests",       "todos"),
        ("nav_sporttrack",   "sport"),
        ("nav_economy",      "economy"),
        ("nav_supplies",     "supplies"),
        ("nav_health_food",  "health_food"),
        ("nav_love",         "love"),
        ("nav_learning",     "learning"),
        ("nav_pomodoro",     "pomodoro"),
        ("nav_music",        "music"),
        ("nav_notes",        "notes"),
        ("nav_reminders",    "reminders"),
        ("nav_calendar",     "calendar"),
        ("nav_crafting",     "crafting"),
        ("nav_shop",         "shop"),
        ("nav_pets",         "pets"),
        ("nav_friends",      "friends"),
        ("nav_guild",        "guild"),
        ("nav_achievement",  "achievements"),
        ("nav_leaderboard",  "leaderboard"),
        ("nav_settings",     "settings"),
    ]
    _AUX_TABS=[]

    def __init__(self):
        super().__init__()
        self.setMinimumWidth(60)
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Expanding)
        self._btns: dict = {}
        self._active = ""
        self._indicator = None
        self._indicator_anim = None
        self._build()
        AppState.register_lang_cb(self.reload_texts)
        self.reload_texts()
        self._select("dashboard")

    def load(self):
        """Update UI text when language changes"""
        self.reload_texts()

    def _build(self):
        outer=QVBoxLayout(self);outer.setContentsMargins(0,0,0,0);outer.setSpacing(0)
        self._scroll=QScrollArea();self._scroll.setWidgetResizable(True);self._scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff);self._scroll.setFrameShape(QFrame.Shape.NoFrame)
        self._inner=QWidget();self._inner.setObjectName("navInner");lay=QVBoxLayout(self._inner);lay.setAlignment(Qt.AlignmentFlag.AlignTop);lay.setContentsMargins(0,6,0,6);lay.setSpacing(2)
        for key_label,key in self._TABS:
            b=QPushButton();b.setCheckable(True);b.setMinimumHeight(40);b.setSizePolicy(QSizePolicy.Policy.Expanding,QSizePolicy.Policy.Minimum);b.setStyleSheet("text-align:center;padding:4px 2px;font-size:13px;");b.clicked.connect(lambda _,k=key:self._select(k));lay.addWidget(b);self._btns[key]=b
        lay.addStretch();self._scroll.setWidget(self._inner);outer.addWidget(self._scroll)
        self._indicator=QFrame(self._inner);self._indicator.setObjectName("navindicator");self._indicator.setVisible(False);self._indicator.lower();self.retheme()

    def reload_texts(self):
        for key_label, key in self._TABS:
            b = self._btns.get(key)
            if b:
                icon = self.ICON_MAP.get(key, "\u2753")
                b.setText(f"{icon}\n{tr(key_label)}")

    def _style(self, active: bool) -> str:
        if active:
            return (f"QPushButton {{ background: transparent; color: #ffffff;"
                    f" border: none; border-radius: 0;"
                    f" font-size: 13px; font-weight: bold;"
                    f" border-left: 3px solid {_T('light')}; }}"
                    f"QPushButton:hover {{ background: rgba(255,255,255,18); }}")
        return (f"QPushButton {{ background: transparent; color: {_T('muted')};"
                f" border: none; border-radius: 0;"
                f" font-size: 13px; font-weight: bold; }}"
                f"QPushButton:hover {{ background: rgba(255,255,255,12);"
                f" color: {_T('text')}; }}")

    def _select(self, key: str):
        self._active = key
        for k, b in self._btns.items():
            b.setChecked(k == key)
            b.setStyleSheet(self._style(k == key))
        SND.click()
        self._move_indicator(key,animate=True)
        if hasattr(self,"_scroll") and key in self._btns:self._scroll.ensureWidgetVisible(self._btns[key],0,18)
        self.tab_changed.emit(key)

    def _move_indicator(self, key: str, animate: bool = True):
        if self._indicator is None:
            return
        b = self._btns.get(key)
        if b is None:
            return
        try:
            g = b.geometry()
            if g.height() < 5:
                return
            target = QRect(g.x() + 5, g.y() + 4, g.width() - 10, g.height() - 8)
            self._indicator.setVisible(True)
            if animate and self._indicator.isVisible():
                if self._indicator_anim is not None:
                    self._indicator_anim.stop()
                a = QPropertyAnimation(self._indicator, b"geometry", self)
                a.setDuration(220)
                a.setStartValue(self._indicator.geometry())
                a.setEndValue(target)
                a.setEasingCurve(QEasingCurve.Type.OutCubic)
                a.start()
                self._indicator_anim = a
            else:
                self._indicator.setGeometry(target)
        except Exception:
            pass

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._move_indicator(self._active, animate=False)

    def retheme(self):
        self.setStyleSheet(f"""
NavBar, QWidget#navInner, QScrollArea {{ background:qlineargradient(x1:0,y1:0,x2:0,y2:1,stop:0 {_T('panel')},stop:1 {_T('bg')}); border:none; }}
NavBar {{ border-right:1px solid {_T('border')}; }}
QScrollBar:vertical {{ background:transparent;width:5px;margin:0; }}
QScrollBar::handle:vertical {{ background:{_T('border')};border-radius:2px;min-height:24px; }}
QScrollBar::add-line:vertical,QScrollBar::sub-line:vertical {{ height:0; }}
""")
        if self._indicator is not None:
            self._indicator.setStyleSheet(
                f"#navindicator {{ border-radius: 12px; border: 1px solid {_T('accent')};"
                f" background: qlineargradient(x1:0,y1:0,x2:1,y2:1,"
                f" stop:0 rgba(124,92,255,95), stop:1 rgba(34,211,238,95)); }}")
        for k, b in self._btns.items():
            b.setStyleSheet(self._style(k == self._active))
        self._move_indicator(self._active, animate=False)


