class _CloudAccountDialog(QDialog):
    def __init__(self, local_user_id, parent=None):
        super().__init__(parent)
        self.local_user_id = local_user_id
        self.setWindowTitle(tr("cloud_account_title")); self.setMinimumWidth(500); self.setStyleSheet(build_ss())
        layout = QVBoxLayout(self); layout.setContentsMargins(22, 20, 22, 20); layout.setSpacing(12)
        info = _lbl(tr("cloud_account_info"), "sub", 10); info.setWordWrap(True); layout.addWidget(info)
        self.email = QLineEdit(); self.email.setPlaceholderText(tr("cloud_email")); layout.addWidget(self.email)
        self.password = QLineEdit(); self.password.setEchoMode(QLineEdit.EchoMode.Password); self.password.setPlaceholderText(tr("cloud_password")); layout.addWidget(self.password)
        self.status = _lbl("", "sub", 10); self.status.setWordWrap(True); layout.addWidget(self.status)
        row = QHBoxLayout(); row.addWidget(_btn(tr("cloud_create_account"), "", self._create_account, 36)); row.addWidget(_btn(tr("cloud_signin_link"), "solid", self._sign_in, 36)); layout.addLayout(row)
        layout.addWidget(_btn(tr("btn_close"), "flat", self.reject, 32))

    def _credentials(self):
        email,password=self.email.text().strip(),self.password.text()
        if "@" not in email or len(password)<8:
            self.status.setText(tr("cloud_credentials_invalid"));return None
        return email,password

    def _create_account(self):
        credentials=self._credentials()
        if not credentials:return
        try:
            from cloud_service import get_cloud_service
            result=get_cloud_service().sign_up(*credentials)
            self.status.setText(tr("cloud_verification_sent") if result.get("verification_required") else tr("cloud_account_created"))
        except Exception as error:
            self.status.setText(tr("cloud_error",error=str(error)))

    def _sign_in(self):
        credentials=self._credentials()
        if not credentials:return
        try:
            from cloud_service import get_cloud_service
            service=get_cloud_service();auth=service.sign_in(*credentials);service.link_local_account(self.local_user_id,auth)
            self.accept()
        except Exception as error:
            self.status.setText(tr("cloud_error",error=str(error)))


class _CloudSyncWorker(QObject):
    finished = pyqtSignal(object)
    def __init__(self, local_user_id, action="sync"):
        super().__init__(); self.local_user_id=local_user_id; self.action=action
    def run(self):
        try:
            from sync_service import get_sync_service
            service=get_sync_service()
            if self.action=="keep_local":
                result=service.resolve_personal_conflict_keep_local(self.local_user_id)
            elif self.action=="use_cloud":
                result=service.resolve_personal_conflict_use_cloud(self.local_user_id)
            elif self.action=="retry":
                result=service.retry_failed_now(self.local_user_id)
            else:
                # Sync Sekarang manual selalu paksa retry agar antrean 32 tidak nyangkut diam
                result=service.sync_now(self.local_user_id, force_retry=True)
            result=dict(result or {});result["cloud_action"]=self.action
            self.finished.emit(result)
        except Exception as error:
            self.finished.emit({"ok":False,"code":"sync_error","error":str(error),"cloud_action":self.action})


class _CloudDeviceManagerDialog(QDialog):
    def __init__(self,local_user_id,parent=None):
        super().__init__(parent);self.local_user_id=local_user_id;self.device=db.get_or_create_cloud_device(local_user_id)
        from cloud_service import get_cloud_service
        self.cloud=get_cloud_service()
        if not (self.cloud.authenticated or self.cloud.restore_session(local_user_id)):raise RuntimeError(tr("cloud_auth_required"))
        self.setWindowTitle(tr("cloud_devices_title"));self.setMinimumSize(600,480);self.setStyleSheet(build_ss())
        layout=QVBoxLayout(self);layout.addWidget(_lbl(tr("cloud_devices_info"),"sub",10));self.list=QListWidget();layout.addWidget(self.list,1)
        row=QHBoxLayout();row.addWidget(_btn(tr("cloud_device_rename"),"solid",self._rename,32));row.addWidget(_btn(tr("cloud_device_revoke"),"danger",self._revoke,32));row.addWidget(_btn(tr("cloud_device_revoke_others"),"danger",self._revoke_others,32));row.addStretch();row.addWidget(_btn(tr("notif_close"),"flat",self.accept,32));layout.addLayout(row);self._load()
    def _load(self):
        self.list.clear()
        def job():
            # Pastikan device saat ini terdaftar di cloud sebelum membaca daftar,
            # supaya perangkat aktif selalu muncul.
            register_error = None
            try:
                row = self.cloud.register_cloud_device(self.device)
                if isinstance(row, list):
                    row = row[0] if row else {}
                if isinstance(row, dict) and row:
                    db.mark_cloud_device_registered(self.local_user_id,
                        row.get("first_seen_at"), row.get("last_seen_at"))
            except Exception as error:
                register_error = str(error)
            devices = self.cloud.get_cloud_devices()
            return devices, register_error
        def ok(payload):
            devices, register_error = payload if isinstance(payload, tuple) else (payload, None)
            if not isinstance(devices, list):
                devices = []
            devices = [d for d in devices if isinstance(d, dict)]
            local_id = str(self.device.get("device_id") or "").lower()

            def _is_current(device):
                for key in ("id", "device_id"):
                    value = device.get(key)
                    if value is not None and str(value).lower() == local_id:
                        return True
                return False

            if register_error:
                self.list.addItem(tr("cloud_device_register_failed", error=register_error))
            seen_current = False
            for device in devices:
                current = _is_current(device)
                seen_current = seen_current or current
                status = tr("cloud_device_revoked") if device.get("revoked_at") else tr("cloud_device_active")
                text = f"{'★ ' if current else ''}{device.get('device_name')} · {device.get('platform')} · {status}\n{tr('cloud_device_last_seen', time=(str(device.get('last_seen_at') or ''))[:19])}"
                item = QListWidgetItem(text)
                item.setData(Qt.ItemDataRole.UserRole, device)
                self.list.addItem(item)
            if not seen_current:
                self.list.addItem(
                    f"★ {self.device.get('device_name') or tr('cloud_device_name_default')} · "
                    f"{self.device.get('platform') or 'desktop'} · {tr('cloud_device_active')}")
            if not devices and not seen_current:
                self.list.addItem(tr("cloud_devices_none_other"))
        def err(error):
            _show(self,tr("gagal_title"),str(error),"error")
        run_in_thread(self,job,on_done=ok,on_error=err)
    def _selected(self):
        item=self.list.currentItem();return item.data(Qt.ItemDataRole.UserRole) if item else None
    def _rename(self):
        device=self._selected()
        if not device or device.get("revoked_at"):return
        value,ok=QInputDialog.getText(self,tr("cloud_device_rename"),tr("cloud_device_name"),QLineEdit.EchoMode.Normal,device.get("device_name") or "")
        if not (ok and value.strip()):return
        def job():
            self.cloud.rename_cloud_device(device["id"],value.strip())
            return device["id"]
        def done(did):
            if str(did)==str(self.device["device_id"]):db.rename_local_cloud_device(self.local_user_id,value.strip());self.device=db.get_or_create_cloud_device(self.local_user_id)
            self._load()
        def err(error):_show(self,tr("gagal_title"),str(error),"error")
        run_in_thread(self,job,on_done=done,on_error=err)
    def _revoke(self):
        device=self._selected()
        if not device:return
        if str(device["id"])==str(self.device["device_id"]):_show(self,tr("info_title"),tr("cloud_device_current_block"),"info");return
        if QMessageBox.question(self,tr("cloud_device_revoke"),tr("cloud_device_revoke_confirm"),QMessageBox.StandardButton.Yes|QMessageBox.StandardButton.No)!=QMessageBox.StandardButton.Yes:return
        def job():
            return self.cloud.revoke_cloud_device(device["id"])
        def done(_):self._load()
        def err(error):_show(self,tr("gagal_title"),str(error),"error")
        run_in_thread(self,job,on_done=done,on_error=err)
    def _revoke_others(self):
        if QMessageBox.question(self,tr("cloud_device_revoke_others"),tr("cloud_device_revoke_others_confirm"),QMessageBox.StandardButton.Yes|QMessageBox.StandardButton.No)!=QMessageBox.StandardButton.Yes:return
        def job():
            return self.cloud.revoke_other_cloud_devices(self.device["device_id"])
        def done(_):self._load()
        def err(error):_show(self,tr("gagal_title"),str(error),"error")
        run_in_thread(self,job,on_done=done,on_error=err)


class SettingsPage(QWidget):
    theme_changed = pyqtSignal()
    language_changed = pyqtSignal()

    def __init__(self, user_id: int):
        super().__init__()

        self.user_id = user_id
        self._admin_was_shown = False
        self._build()
        AppState.register_lang_cb(self._retranslate)
        AppState.register(self._check_admin_panel)

    def _retranslate(self):
        self.page_header.retranslate()
        self.theme_group.setTitle(tr("settings_theme"))
        self.sound_group.setTitle(tr("settings_sound"))
        self.currency_group.setTitle(tr("settings_currency"))
        self.lang_group.setTitle(tr("settings_language"))
        self.db_group.setTitle(tr("settings_database"))
        self._snd.setText(tr("settings_sound_enable"))
        self.exit_btn.setText(tr("settings_exit"))
        self.sound_hint.setText(tr("settings_sound_hint"))
        self.db_path_label.setText(tr("settings_db_path", path=db.DB_PATH))
        self.lang_combo.setItemText(0, tr("lang_id"))
        self.lang_combo.setItemText(1, tr("lang_en"))
        if hasattr(self,"cloud_group"):
            self.cloud_group.setTitle(tr("cloud_group"));self.cloud_link_btn.setText(tr("cloud_link_account"));self.cloud_sync_btn.setText(tr("cloud_sync_now"));self.cloud_migrate_btn.setText(tr("cloud_migrate_local"));self.cloud_signout_btn.setText(tr("cloud_sign_out"));self.cloud_inspect_btn.setText(tr("cloud_queue_inspect"));self.cloud_retry_btn.setText(tr("cloud_queue_retry"))
            self.cloud_keep_local_btn.setText(tr("cloud_conflict_keep_local"));self.cloud_use_remote_btn.setText(tr("cloud_conflict_use_remote"));self.cloud_devices_btn.setText(tr("cloud_devices_title"))
        if hasattr(self, "a11y_group"):
            self.a11y_group.setTitle(tr("a11y_group"))
            self._a11y_font_lbl.setText(tr("a11y_font_scale"))
            self.a11y_font_hint.setText(tr("a11y_font_apply_hint"))
            self._hc.setText(tr("a11y_high_contrast"))
        if hasattr(self, "update_group"):
            self.update_group.setTitle(tr("update_group_title"))
            self.update_check_btn.setText(tr("update_check"))
            self.update_version_lbl.setText(tr("update_version", version=self._app_version()))

    def load(self):
        self._retranslate()
        self._refresh_theme_selection()
        if hasattr(self,"cloud_status_lbl"):self._refresh_cloud_status()

    def _check_admin_panel(self):
        """Tampilkan admin panel jika user baru menjadi admin tanpa restart."""
        is_admin = bool(AppState.user().get("is_admin", 0))
        if is_admin and not self._admin_was_shown:
            self._admin_was_shown = True
            # Cari layout container dalam scroll area
            scroll = self.findChild(QScrollArea)
