#  NOTIFICATION POPUP
# ══════════════════════════════════════════════════════════════════════════════
class NotifPopup(QDialog):
    """Phase 4D notification center backed by Realtime cloud cache and SQLite."""
    def __init__(self,user_id:int,parent=None):
        super().__init__(parent);self.user_id=user_id;self.page_size=50;self.cloud=None
        self.setWindowTitle(tr("notif_window_title"));self.setMinimumSize(620,560);self.setStyleSheet(build_ss())
        layout=QVBoxLayout(self);layout.setContentsMargins(20,20,20,20);layout.setSpacing(10)
        head=QHBoxLayout();head.addWidget(_lbl(tr("notif_title"),"section",14,True));head.addStretch()
        self.filter=QComboBox();self.filter.addItem(tr("notif_filter_all"),"all")
        for label,key in ((tr("notif_filter_message"),"direct_message"),(tr("notif_filter_social"),"friendship"),(tr("notif_filter_love"),"couple"),(tr("notif_filter_pvp"),"online_pvp"),(tr("notif_filter_guild"),"guild"),(tr("notif_filter_security"),"device")):self.filter.addItem(label,key)
        self.filter.currentIndexChanged.connect(self._reset);head.addWidget(self.filter);layout.addLayout(head)
        self.list=QListWidget();self.list.itemDoubleClicked.connect(lambda _:self._open_selected());layout.addWidget(self.list,1)
        actions=QHBoxLayout();actions.addWidget(_btn(tr("notif_open"),"diamond",self._open_selected,32));actions.addWidget(_btn(tr("notif_mark_read"),"solid",self._mark_selected,32));actions.addWidget(_btn(tr("notif_mark_all"),"gold",self._mark_all,32));actions.addStretch();actions.addWidget(_btn(tr("notif_load_more"),slot=self._load_more,h=32));actions.addWidget(_btn(tr("notif_close"),"danger",self.accept,32));layout.addLayout(actions)
        self._connect_cloud();self._render();self._refresh_cloud(on_done=self._render)

    def _connect_cloud(self):
        if not db.get_cloud_user_link(self.user_id):return
        try:
            from cloud_service import get_cloud_service
            cloud=get_cloud_service()
            if cloud.authenticated or cloud.restore_session(self.user_id):self.cloud=cloud
        except Exception:pass

    def _refresh_cloud(self,before=None,on_done=None):
        if not self.cloud:
            if on_done:on_done()
            return
        def job():
            return self.cloud.get_social_notifications_page(100,before,None)
        def ok(rows):
            try:db.cache_cloud_notifications(self.user_id,rows)
            except Exception:pass
            if on_done:on_done()
        def err(_):
            if on_done:on_done()
        run_in_thread(self,job,on_done=ok,on_error=err)

    def _reset(self):self.page_size=50;self._render()

    def _render(self):
        rows=db.get_notification_center(self.user_id,self.page_size,0,self.filter.currentData());self.list.clear()
        icons={"levelup":"🎉","success":"✅","danger":"💀","info":"💬","warning":"⚠️"}
        for row in rows:
            unread="● " if not row.get("is_read") else ""
            item=QListWidgetItem(f"{unread}{icons.get(row.get('type'),'💬')} {row.get('message','')}\n   {(row.get('created_at') or '')[:16]}")
            item.setData(Qt.ItemDataRole.UserRole,row);self.list.addItem(item)
        if not rows:self.list.addItem(tr("notif_empty"))

    def _load_more(self):
        current=db.get_notification_center(self.user_id,self.page_size,0,self.filter.currentData())
        before=next((row.get("created_at") for row in reversed(current) if row.get("cloud_id")),None)
        self.page_size=min(500,self.page_size+50);self._render()
        self._refresh_cloud(before,on_done=self._render)

    def _mark_selected(self):
        item=self.list.currentItem();row=item.data(Qt.ItemDataRole.UserRole) if item else None
        if not row:return
        cloud_id=db.mark_notification_read(self.user_id,row["id"])
        if cloud_id and self.cloud:
            def job():
                return self.cloud.mark_social_notification_read(cloud_id)
            def done(_):self._render()
            run_in_thread(self,job,on_done=done,on_error=lambda e: self._render())
        else:
            self._render()

    def _mark_all(self):
        db.mark_read(self.user_id)
        if self.cloud:
            def job():
                return self.cloud.mark_social_notifications_read()
            def done(_):self._render()
            run_in_thread(self,job,on_done=done,on_error=lambda e: self._render())
        else:
            self._render()

    def _open_selected(self):
        item=self.list.currentItem();row=item.data(Qt.ItemDataRole.UserRole) if item else None
        if not row:return
        self._mark_selected();entity=row.get("entity_type") or "";main=self.parent()
        page="friends"
        if entity in ("guild","online_guild","guild_battle"):page="guild"
        elif entity in ("love_space","love_photo"):page="love"
        elif entity=="device":page="settings"
        elif entity=="conversation" and row.get("actor_cloud_id"):
            friend_id=db.get_local_user_id_for_cloud(row["actor_cloud_id"])
            if friend_id:
                friend=db.get_user(friend_id) or {};ChatDialog(self.user_id,friend_id,friend.get("display_name") or friend.get("username") or tr("chat_friend"),main).exec();return
        if hasattr(main,"_nav") and hasattr(main,"_switch"):main._nav._select(page);main._switch(page);self.accept()


