#  LeaderBoard
# ══════════════════════════════════════════════════════════════════════════════
class LeaderboardPage(QWidget):
    def __init__(self):
        super().__init__()
        layout = QVBoxLayout(self)
        layout.setContentsMargins(22, 18, 22, 18)
        layout.setSpacing(12)
        header=_page_header("leaderboard");self.mode_combo=QComboBox();self.mode_combo.addItem(tr("cloud_leaderboard_productivity"),"cloud_productivity");self.mode_combo.addItem(tr("cloud_leaderboard_guild"),"cloud_guild");self.mode_combo.addItem(tr("cloud_leaderboard_local"),"local");self.mode_combo.currentIndexChanged.connect(self.load);header.add_action(self.mode_combo);layout.addWidget(header)

        self.table = QTableWidget()
        self.table.setColumnCount(7)
        self._update_headers()

        self.table.setEditTriggers(QTableWidget.EditTrigger.NoEditTriggers)
        self.table.setSelectionMode(QTableWidget.SelectionMode.NoSelection)
        self.table.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.table.horizontalHeader().setSectionsMovable(False)
        self.table.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Stretch)
        self.table.verticalHeader().setVisible(False)
        self.table.setAlternatingRowColors(True)

        layout.addWidget(self.table)
        AppState.register(self.load)
        AppState.register_lang_cb(self._retranslate)
        self.load()

    def _update_headers(self):
        self.table.setHorizontalHeaderLabels([
            tr("leaderboard_col_user"),
            tr("leaderboard_col_level"),
            tr("leaderboard_col_xp"),
            tr("leaderboard_col_gold"),
            tr("leaderboard_col_sport"),
            tr("leaderboard_col_pet"),
            tr("leaderboard_col_rebirth")
        ])

    def _retranslate(self):
        self._update_headers()

    def load(self):
        # Terapkan style agar background sesuai tema
        self.table.setStyleSheet(f"""
            QTableWidget {{
                background-color: {_T("panel")};
                alternate-background-color: {_T("border")};
                gridline-color: {_T("border")};
                border: 1px solid {_T("border")};
                border-radius: 6px;
                color: {_T("text")};
            }}
            QHeaderView::section {{
                background-color: {_T("primary")};
                color: {_T("light")};
                padding: 8px;
                font-weight: bold;
                border: 1px solid {_T("border")};
            }}
        """)

        mode=self.mode_combo.currentData()
        if mode!="local" and db.get_cloud_user_link(AppState.user_id):
            from cloud_service import get_cloud_service
            cloud=get_cloud_service()

            def job():
                if not (cloud.authenticated or cloud.restore_session(AppState.user_id)):
                    raise RuntimeError("no_cloud_session")
                return (cloud.get_online_guild_leaderboard(50) if mode=="cloud_guild" else cloud.get_global_productivity_leaderboard(30,50))

            def ok(data):
                try:self._render_cloud_leaderboard(data,mode)
                except Exception as error:
                    log.warning(f"Cloud leaderboard gagal: {error}")

            def err(error):
                log.warning(f"Cloud leaderboard gagal: {error}")

            run_in_thread(self,job,on_done=ok,on_error=err)
            return
        data = db.get_leaderboard_for_user(AppState.user_id)
        self._update_headers()
        self.table.setRowCount(len(data))
        # Map title key → nama terlokalisasi
        lang = AppState.get_language()
        tmap = {t["key"]: (t["name"][0] if lang == "id" else t["name"][1])
                for t in db.TITLES}
        partners = db.get_couple_partners_map()
        for i, r in enumerate(data):
            name_txt = r["display_name"] or r["username"]
            title_txt = tmap.get(r.get("selected_title") or "", "")
            if title_txt:
                name_txt = f"{name_txt}  {title_txt}"
            partner = partners.get(r["id"])
            if partner:
                name_txt = f"{name_txt}  💞"
            user_item = QTableWidgetItem(name_txt)
            user_item.setToolTip(tr("leaderboard_partner_tip", name=partner[1]) if partner else tr("leaderboard_single_tip"))
            if partner:
                user_item.setForeground(QColor("#ff7bac"))
            self.table.setItem(i, 0, user_item)
            self.table.setItem(i, 1, QTableWidgetItem(str(r["level"])))
            self.table.setItem(i, 2, QTableWidgetItem(str(r["total_xp_earned"])))
            self.table.setItem(i, 3, QTableWidgetItem(f"{r['gold']:.0f}"))
            sport_lv = r.get("sport_level", 1) or 1
            sport_item = QTableWidgetItem(f"Lv.{sport_lv}")
            sport_item.setForeground(QColor("#f0a800"))
            self.table.setItem(i, 4, sport_item)
            self.table.setItem(i, 5, QTableWidgetItem(str(r["pet_count"])))
            rebirth_item = QTableWidgetItem(str(r.get("rebirth_count", 0)))
            rebirth_item.setForeground(QColor("#ff6b00"))
            self.table.setItem(i, 6, rebirth_item)

    def _render_cloud_leaderboard(self,data,mode):
        self.table.clearContents();self.table.setRowCount(len(data));self.table.setColumnCount(7)
        if mode=="cloud_guild":
            headers=[tr("leaderboard_rank"),tr("leaderboard_guild"),tr("leaderboard_col_level"),tr("cloud_leaderboard_exp"),tr("cloud_leaderboard_members"),"",""]
        else:
            headers=[tr("leaderboard_rank"),tr("leaderboard_col_user"),tr("cloud_leaderboard_points"),tr("cloud_leaderboard_events"),"","",""]
        self.table.setHorizontalHeaderLabels(headers)
        for index,row in enumerate(data):
            values=([index+1,row.get("name",""),row.get("level",1),row.get("exp",0),row.get("member_count",0),"",""] if mode=="cloud_guild"
                    else [index+1,row.get("display_name") or row.get("username",""),row.get("total_points",0),row.get("event_count",0),"","",""])
            for column,value in enumerate(values):self.table.setItem(index,column,QTableWidgetItem(str(value)))

    def closeEvent(self, e):
        AppState.unregister(self.load)
        AppState.unregister_lang_cb(self._retranslate)
        super().closeEvent(e)

# ══════════════════════════════════════════════════════════════════════════════
#  Friends Page (Add Friend System)
# ══════════════════════════════════════════════════════════════════════════════
class FriendsPage(QWidget):
    def __init__(self, user_id):
        super().__init__()

        self.user_id = user_id
        self.main_layout = None  # referensi layout utama
        self._build()
        AppState.register(self.load)

    def _build(self):
        self.main_layout = QVBoxLayout(self)
        self.main_layout.setContentsMargins(22, 18, 22, 18)
        self.main_layout.setSpacing(12)
        self.main_layout.addWidget(_page_header("friends"))

        # Form tambah teman
        add_form = QHBoxLayout()
        self.friend_username = _input(tr("friends_add_placeholder"))
        add_btn = _btn(tr("friends_add_btn"), "solid", self._send_request)
        add_form.addWidget(self.friend_username)
        add_form.addWidget(add_btn)
        self.main_layout.addLayout(add_form)

        # Daftar permintaan masuk
        self.pending_group = QGroupBox(tr("friends_pending"))
        self.pending_layout = QVBoxLayout(self.pending_group)
        self.main_layout.addWidget(self.pending_group)

        self.couple_requests_group = QGroupBox(tr("couple_requests_title"))
        self.couple_requests_layout = QVBoxLayout(self.couple_requests_group)
        self.main_layout.addWidget(self.couple_requests_group)

        # Daftar teman
        self.friends_group = QGroupBox(tr("friends_list"))
        self.friends_layout = QVBoxLayout(self.friends_group)
        self.main_layout.addWidget(self.friends_group)

        # ⚔️ PvP Streak Battle
        self.pvp_group = QGroupBox(tr("pvp_section"))
        self.pvp_layout = QVBoxLayout(self.pvp_group)
        self.main_layout.addWidget(self.pvp_group)

        self.main_layout.addStretch()
        self.load()

    def _clear_layout(self):
        """Hapus semua widget dan sub-layout dari layout utama."""
        if self.main_layout:
            while self.main_layout.count():
                item = self.main_layout.takeAt(0)
                if item.widget():
                    item.widget().deleteLater()
                elif item.layout():
                    # Bersihkan sub-layout juga
                    sub_layout = item.layout()
                    while sub_layout.count():
                        sub_item = sub_layout.takeAt(0)
                        if sub_item.widget():
                            sub_item.widget().deleteLater()
                    sub_layout.deleteLater()

    def load(self):
        if not AppState.user_id:
            return

        # ========== CEK ADMIN ==========
        if AppState.user().get("is_admin", 0):
            self._clear_layout()
            msg = QLabel(tr("friends_admin_block"))
            msg.setAlignment(Qt.AlignmentFlag.AlignCenter)
            msg.setStyleSheet(f"color:{_T('muted')}; font-size:14px; padding:40px;")
            self.main_layout.addWidget(msg)
            return

        # ========== NON-ADMIN: TAMPILKAN UI NORMAL ==========
        # Bersihkan isi pending_layout dan friends_layout (tapi jangan hapus group box-nya)
        while self.pending_layout.count():
            item = self.pending_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
            elif item.layout():
                sub = item.layout()
                while sub.count():
                    sub_item = sub.takeAt(0)
                    if sub_item.widget():
                        sub_item.widget().deleteLater()
                sub.deleteLater()

        while self.friends_layout.count():
            item = self.friends_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
            elif item.layout():
                sub = item.layout()
                while sub.count():
                    sub_item = sub.takeAt(0)
                    if sub_item.widget():
                        sub_item.widget().deleteLater()
                sub.deleteLater()

        while self.couple_requests_layout.count():
            item = self.couple_requests_layout.takeAt(0)
            if item.widget(): item.widget().deleteLater()
            elif item.layout():
                while item.layout().count():
                    child = item.layout().takeAt(0)
                    if child.widget(): child.widget().deleteLater()

        # Pending friend requests
        pending = db.get_pending_friend_requests(self.user_id)
        if pending:
            self.pending_group.setVisible(True)
            for req in pending:
                row = QHBoxLayout(); row.setSpacing(9)
                sender = db.get_user(req.get("sender_id"))
                row.addWidget(_user_photo_label(sender, 38))
                identity = QVBoxLayout(); identity.addWidget(_lbl(req['display_name'], size=11, bold=True)); identity.addWidget(_lbl(f"@{req['username']}", "sub", 9))
                row.addLayout(identity, 1)
                accept = _btn(tr("guild_accept"), h=28)
                accept.clicked.connect(lambda _, rid=req["id"]: self._accept(rid))
                reject = _btn(tr("guild_reject"), "danger", h=28)
                reject.clicked.connect(lambda _, rid=req["id"]: self._reject(rid))
                row.addWidget(accept)
                row.addWidget(reject)
                self.pending_layout.addLayout(row)
        else:
            self.pending_group.setVisible(False)

        couple_requests = db.get_pending_couple_requests(self.user_id)
        self.couple_requests_group.setVisible(bool(couple_requests))
        for request in couple_requests:
            row = QHBoxLayout(); row.setSpacing(9)
            other = db.get_user(request["other_user_id"])
            row.addWidget(_user_photo_label(other, 38))
            info = QVBoxLayout(); info.addWidget(_lbl(request["other_display_name"], size=11, bold=True))
            info.addWidget(_lbl(tr("couple_request_outgoing") if request["direction"] == "outgoing" else tr("couple_request_incoming"), "sub", 9))
            row.addLayout(info, 1)
            if request["direction"] == "incoming":
                accept = _btn(tr("couple_accept"), "solid", h=28)
                accept.clicked.connect(lambda _, rid=request["id"]: self._respond_couple(rid, True))
                reject = _btn(tr("couple_reject"), "danger", h=28)
                reject.clicked.connect(lambda _, rid=request["id"]: self._respond_couple(rid, False))
                row.addWidget(accept); row.addWidget(reject)
            else:
                cancel = _btn(tr("couple_cancel"), "danger", h=28)
                cancel.clicked.connect(lambda _, rid=request["id"]: self._cancel_couple(rid))
                row.addWidget(cancel)
            self.couple_requests_layout.addLayout(row)

        # Friends list
        friends = db.get_friends(self.user_id)
        if friends:
            self.friends_group.setVisible(True)
            for f in friends:
                card = _card(); row = QHBoxLayout(card); row.setContentsMargins(10, 8, 10, 8); row.setSpacing(10)
                row.addWidget(_user_photo_label(f, 44))
                relation = db.get_couple_status_between(self.user_id, f["id"])
                status = relation.get("status", "friend")
                info = QVBoxLayout(); info.setSpacing(2)
                info.addWidget(_lbl(f["display_name"], size=12, bold=True))
                status_text = tr("couple_status_couple") if status == "accepted" else tr("couple_status_pending") if status == "pending" else tr("couple_status_friend")
                presence=db.get_cached_presence(f.get("cloud_user_id")) if f.get("cloud_user_id") else {}
                presence_text=tr("presence_online") if presence.get("status")=="online" else tr("presence_offline")
                status_lbl = _lbl(f"Lv {f['level']} · {status_text} · {presence_text}", "sub", 9); info.addWidget(status_lbl)
                row.addLayout(info, 1)
                if status not in ("accepted","pending"):
                    couple_btn=_btn(tr("couple_connect"),"diamond",h=28);couple_btn.clicked.connect(lambda _,fid=f["id"]:self._send_couple_request(fid));row.addWidget(couple_btn)
                elif status=="accepted":
                    end_btn=_btn(tr("couple_end"),"danger",h=28);end_btn.clicked.connect(lambda _,fid=f["id"]:self._end_couple(fid));row.addWidget(end_btn)
                pvp_btn = _btn("⚔️", "gold", h=28); pvp_btn.setToolTip(tr("pvp_btn"))
                pvp_btn.clicked.connect(lambda _, fid=f["id"]: self._challenge_pvp(fid))
                unread=(db.get_cloud_unread_count(self.user_id,f["id"]) if db.get_cloud_user_link(self.user_id) and f.get("cloud_user_id")
                        else db.get_unread_count_between(self.user_id,f["id"]))
                chat_text=tr("friends_chat_unread",count=unread) if unread else tr("friends_chat_btn")
                chat_btn = _btn(chat_text, h=28)
                chat_btn.clicked.connect(lambda _, fid=f["id"], name=f["display_name"]: self._open_chat(fid, name))
                profile_btn = _btn(tr("friends_profile_short"), h=28)
                profile_btn.clicked.connect(lambda _, fid=f["id"]: self._view_profile(fid))
                kick_btn = _btn(tr("friends_remove_btn"), "danger", h=28)
                kick_btn.clicked.connect(lambda _, fid=f["id"]: self._remove_friend(fid))
                row.addWidget(chat_btn); row.addWidget(profile_btn); row.addWidget(pvp_btn); row.addWidget(kick_btn)
                self.friends_layout.addWidget(card)
        else:
            self.friends_group.setVisible(False)

        self._render_pvp()

    # ── ⚔️ PvP STREAK BATTLE ─────────────────────────────────────────────────
    def _clear_pvp_layout(self):
        while self.pvp_layout.count():
            item = self.pvp_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
            elif item.layout():
                sub = item.layout()
                while sub.count():
                    si = sub.takeAt(0)
                    if si.widget():
                        si.widget().deleteLater()

    def _render_pvp(self):
        self._clear_pvp_layout()
        if db.get_cloud_user_link(self.user_id):
            def job():
                cloud=self._cloud_social_service()
                if not cloud:
                    return None
                items=cloud.get_online_pvp_challenges();current=cloud.current_cloud_user_id
                scores={}
                for item in (items or [])[:8]:
                    if item.get("status")=="active":
                        try:
                            opp = item["opponent_id"] if item["challenger_id"]==current else item["challenger_id"]
                            scores[item["id"]]=(cloud.get_online_pvp_score(item["id"],current) or 0, cloud.get_online_pvp_score(item["id"],opp) or 0)
                        except Exception:
                            scores[item["id"]]=(0,0)
                return {"items":items,"current":current,"scores":scores}
            def done(data):
                if data:
                    self._render_cloud_pvp(data)
                else:
                    self._render_local_pvp()
            def err(_):
                self._render_local_pvp()
            run_in_thread(self, job, on_done=done, on_error=err)
            return
        self._render_local_pvp()

    def _render_local_pvp(self):
        try:
            items = db.get_pvp_challenges(self.user_id)
        except Exception:
            items = []
        u = AppState.user() or {}
        my_name = u.get("display_name") or u.get("username", "")
        shown = 0
        for it in items:
            if it["status"] == "declined":
                continue
            shown += 1
            if shown > 6:
                break
            card = _card()
            box = QVBoxLayout(card)
            box.setSpacing(6)
            status = it["status"]
            if status == "pending" and not it["is_challenger"]:
                box.addWidget(_lbl(f"⚔️ {it['opponent_name']}", size=12, bold=True))
                btns = QHBoxLayout()
                acc = _btn(tr("pvp_accept"), "solid", h=30)
                acc.clicked.connect(
                    lambda _, cid=it["id"]: self._respond_pvp(cid, True))
                dec = _btn(tr("pvp_decline"), "danger", h=30)
                dec.clicked.connect(
                    lambda _, cid=it["id"]: self._respond_pvp(cid, False))
                btns.addWidget(acc)
                btns.addWidget(dec)
                box.addLayout(btns)
            elif status == "pending":
                lbl = _lbl(tr("pvp_pending_out", name=it["opponent_name"]),
                           "sub", 11)
                lbl.setWordWrap(True)
                box.addWidget(lbl)
            elif status == "active":
                lbl = _lbl(tr("pvp_score_line", me=my_name,
                              opp=it["opponent_name"],
                              ms=it.get("my_score", 0),
                              os=it.get("opponent_score", 0),
                              days=it.get("days_left", 0)), size=11)
                lbl.setWordWrap(True)
                box.addWidget(lbl)
            elif status == "finished":
                if it.get("winner_id") is None:
                    key = "pvp_finished_tie"
                elif it.get("winner_id") == self.user_id:
                    key = "pvp_finished_win"
                else:
                    key = "pvp_finished_lose"
                lbl = _lbl(tr(key, name=it["opponent_name"],
                              ms=it.get("my_score", 0),
                              os=it.get("opponent_score", 0)), size=11)
                lbl.setWordWrap(True)
                box.addWidget(lbl)
            else:
                continue
            self.pvp_layout.addWidget(card)
        if shown == 0:
            none_lbl = _lbl(tr("pvp_none"), "sub", 11)
            none_lbl.setWordWrap(True)
            self.pvp_layout.addWidget(none_lbl)

    def _render_cloud_pvp(self, data):
        items=data["items"];current=data["current"];scores=data["scores"]
        if not items:
            self.pvp_layout.addWidget(_lbl(tr("cloud_pvp_empty"),"sub",11));return
        for item in items[:8]:
            opponent_cloud=item["opponent_id"] if item["challenger_id"]==current else item["challenger_id"]
            opponent_local=db.get_local_user_id_for_cloud(opponent_cloud);opponent=db.get_user(opponent_local) if opponent_local else {}
            card=_card();box=QVBoxLayout(card);box.setSpacing(6)
            box.addWidget(_lbl(f"{opponent.get('display_name') or opponent.get('username') or 'Cloud User'} · {item['status']}",size=11,bold=True))
            if item["status"]=="active":
                mine,theirs=scores.get(item["id"],(0,0))
                box.addWidget(_lbl(tr("cloud_pvp_score",mine=mine,theirs=theirs),"sub",10))
                box.addWidget(_btn(tr("cloud_pvp_finalize"),"gold",slot=lambda _,cid=item["id"]:self._finalize_cloud_pvp(cid),h=28))
            elif item["status"]=="pending" and item["opponent_id"]==current:
                row=QHBoxLayout();row.addWidget(_btn(tr("couple_accept"),"solid",slot=lambda _,cid=item["id"]:self._respond_cloud_pvp(cid,True),h=28));row.addWidget(_btn(tr("couple_reject"),"danger",slot=lambda _,cid=item["id"]:self._respond_cloud_pvp(cid,False),h=28));box.addLayout(row)
            elif item["status"]=="pending":
                box.addWidget(_btn(tr("couple_cancel"),"danger",slot=lambda _,cid=item["id"]:self._cancel_cloud_pvp(cid),h=28))
            elif item["status"]=="completed":
                box.addWidget(_btn(tr("cloud_pvp_claim"),"gold",slot=lambda _,cid=item["id"]:self._claim_cloud_pvp(cid),h=28))
            self.pvp_layout.addWidget(card)

    def _respond_cloud_pvp(self,challenge_id,accept):
        def job():
            self._cloud_social_service().respond_online_pvp_challenge(challenge_id,accept)
            return None
        def ok(_):
            SND.complete(); self.load()
        self._run_cloud_job(job, on_ok=ok, sync_after=False)

    def _cancel_cloud_pvp(self,challenge_id):
        def job():
            self._cloud_social_service().cancel_online_pvp_challenge(challenge_id)
            return None
        def ok(_):
            self.load()
        self._run_cloud_job(job, on_ok=ok, sync_after=False)

    def _finalize_cloud_pvp(self,challenge_id):
        def job():
            self._cloud_social_service().finalize_online_pvp(challenge_id)
            return None
        def ok(_):
            SND.complete(); self.load()
        def err(error):
            _show(self,tr("info_title"),str(error),"info"); self.load()
        self._run_cloud_job(job, on_ok=ok, on_err=err, sync_after=False)

    def _claim_cloud_pvp(self,challenge_id):
        def job():
            return self._cloud_social_service().claim_online_pvp_reward(challenge_id)
        def ok(reward):
            reward = reward or {}
            try:
                db.gain_xp_gold(self.user_id,int(reward.get("xp_reward",0)),int(reward.get("gold_reward",0)))
                AppState.refresh()
            except Exception:
                pass
            _show(self,tr("berhasil_title"),tr("cloud_pvp_reward",xp=reward.get("xp_reward",0),gold=reward.get("gold_reward",0)),"success")
        self._run_cloud_job(job, on_ok=ok, sync_after=False)

    def _respond_pvp(self, challenge_id: int, accept: bool):
        r = db.respond_pvp_challenge(challenge_id, self.user_id, accept)
        if r.get("ok"):
            SND.notify()
        QTimer.singleShot(0, self.load)

    def _challenge_pvp(self, friend_id: int):
        def job():
            cloud=self._cloud_social_service();opponent=db.get_user(friend_id).get("cloud_user_id")
            if cloud:
                if not opponent:raise RuntimeError(tr("cloud_friend_not_linked"))
                cloud.send_online_pvp_challenge(opponent,7);return {"ok":True,"msg":tr("cloud_pvp_sent")}
            return db.send_pvp_challenge(self.user_id,friend_id)
        def ok(r):
            self._show_result(r)
            QTimer.singleShot(0, self.load)
        self._run_cloud_job(job, on_ok=ok, sync_after=False)

    def _cloud_social_service(self):
        if not db.get_cloud_user_link(self.user_id): return None
        from cloud_service import get_cloud_service
        service=get_cloud_service()
        if not (service.authenticated or service.restore_session(self.user_id)):
            raise RuntimeError(tr("cloud_auth_required"))
        return service

    def _sync_after_cloud_action(self):
        """Jalankan sync_now di background thread agar tidak membekukan UI."""
        def job():
            from sync_service import get_sync_service
            return get_sync_service().sync_now(self.user_id)

        def done(_):
            AppState.refresh(); self.load()

        def fail(error):
            log.warning(f"sync setelah aksi cloud gagal: {error}")
            AppState.refresh(); self.load()

        run_in_thread(self, job, on_done=done, on_error=fail)

    def _run_cloud_job(self, job, on_ok=None, on_err=None, sync_after=True):
        """Jalankan aksi cloud di background thread; hasil dikirim ke UI thread."""
        def done(result):
            if sync_after:
                try:
                    self._sync_after_cloud_action()
                except Exception:
                    pass
            if on_ok:
                on_ok(result)

        def fail(error):
            if on_err:
                on_err(str(error))
            else:
                _show(self, tr("gagal_title"), str(error), "error")

        run_in_thread(self, job, on_done=done, on_error=fail)

    def _send_couple_request(self, friend_id):
        def job():
            cloud=self._cloud_social_service()
            cloud_friend=db.get_user(friend_id).get("cloud_user_id")
            if cloud:
                if not cloud_friend: raise RuntimeError(tr("cloud_friend_not_linked"))
                cloud.send_couple_request(cloud_friend);return {"ok":True,"code":"pending"}
            return db.send_couple_request(self.user_id,friend_id)
        def ok(result):
            key = f"couple_result_{result.get('code', 'error')}"
            _show(self, tr("couple_title"), result.get("detail") or tr(key), "success" if result.get("ok") else "error")
            if result.get("ok"): SND.complete()
            self.load()
        self._run_cloud_job(job, on_ok=ok)

    def _respond_couple(self, relationship_id, accept):
        def job():
            cloud=self._cloud_social_service();record=db.get_couple_relationship_record(relationship_id,self.user_id)
            if cloud and record.get("cloud_id"):
                data=cloud.respond_couple_request(record["cloud_id"],accept)
                status=(data or {}).get("status","accepted" if accept else "rejected") if isinstance(data,dict) else ("accepted" if accept else "rejected")
                return {"ok":True,"code":status}
            if cloud: raise RuntimeError(tr("cloud_relationship_not_synced"))
            return db.respond_couple_request(self.user_id,relationship_id,accept)
        def ok(result):
            key = f"couple_result_{result.get('code', 'error')}"
            _show(self, tr("couple_title"), result.get("detail") or tr(key), "success" if result.get("ok") else "error")
            if result.get("ok"): SND.complete(); AppState.refresh()
            self.load()
        self._run_cloud_job(job, on_ok=ok)

    def _cancel_couple(self, relationship_id):
        def job():
            cloud=self._cloud_social_service();record=db.get_couple_relationship_record(relationship_id,self.user_id)
            if cloud and record.get("cloud_id"):
                cloud.cancel_couple_request(record["cloud_id"]);return {"ok":True,"code":"cancelled"}
            if cloud: raise RuntimeError(tr("cloud_relationship_not_synced"))
            return db.cancel_couple_request(self.user_id,relationship_id)
        def ok(result):
            _show(self,tr("couple_title"),result.get("detail") or tr(f"couple_result_{result.get('code','error')}"),"success" if result.get("ok") else "error")
            self.load()
        self._run_cloud_job(job, on_ok=ok)

    def _end_couple(self,friend_id):
        relation=db.get_couple_status_between(self.user_id,friend_id)
        if relation.get("status")!="accepted":return
        if QMessageBox.question(self,tr("couple_end_title"),tr("couple_end_confirm"),QMessageBox.StandardButton.Yes|QMessageBox.StandardButton.No)!=QMessageBox.StandardButton.Yes:return
        try:
            # Offline-first: akhiri relasi secara lokal TANPA mewajibkan akun cloud.
            ended=db.end_local_couple_relationship(self.user_id,relation["id"])
            if not ended.get("ok"):raise RuntimeError(tr("couple_result_invalid_request"))
            _queue_cloud_couple_end(self.user_id,relation)
            SND.click();_show(self,tr("couple_end_title"),tr("couple_end_local_success"),"success");self.load()
        except Exception as error:_show(self,tr("gagal_title"),str(error),"error")

    def _open_chat(self, friend_id, friend_name):
        if AppState.user().get("is_admin", 0):
            _show(self, tr("info_title"), tr("chat_admin_block"), "warning")
            return
        dlg = ChatDialog(self.user_id, friend_id, friend_name, self)
        dlg.exec()

    def _view_profile(self, friend_id):
        dlg = FriendProfileDialog(friend_id, self)
        dlg.exec()

    def _remove_friend(self, friend_id):
        def job():
            cloud=self._cloud_social_service();record=db.get_friendship_between(self.user_id,friend_id)
            couple=db.get_couple_status_between(self.user_id,friend_id)
            if cloud and couple.get("status")=="accepted" and couple.get("cloud_id"):
                # Best-effort: akhiri Couple di cloud sebelum memutus pertemanan.
                try:cloud.end_couple_relationship(couple["cloud_id"])
                except Exception:pass
            if cloud and record.get("cloud_id"):
                cloud.remove_friendship(record["cloud_id"]);return {"ok":True,"msg":tr("cloud_friend_removed")}
            if cloud:raise RuntimeError(tr("cloud_friendship_not_synced"))
            return db.remove_friend(self.user_id,friend_id)
        def ok(r):
            if r["ok"]:
                SND.notify()
                _show(self, tr("berhasil_title"), r["msg"], "success")
            else:
                SND.error()
                _show(self, tr("gagal_title"), r["msg"], "error")
            QTimer.singleShot(0, self.load)
        self._run_cloud_job(job, on_ok=ok)

    def _send_request(self):
        username = self.friend_username.text().strip()
        if not username:
            _show(self, tr("msg_error"), tr("msg_enter_username"), "error")
            return
        def job():
            cloud=self._cloud_social_service()
            if cloud:
                cloud.send_friend_request(username);return {"ok":True,"msg":tr("cloud_friend_request_sent")}
            return db.send_friend_request(self.user_id,username)
        def ok(r):
            if r["ok"]:
                SND.notify()
                _show(self, tr("berhasil_title"), r["msg"], "success")
                self.friend_username.clear()
            else:
                SND.error()
                _show(self, tr("gagal_title"), r["msg"], "error")
        self._run_cloud_job(job, on_ok=ok)

    def _accept(self, req_id):
        self._respond_friend_request(req_id, True, on_done=lambda r: (self._show_result(r), QTimer.singleShot(0, self.load)))

    def _reject(self, req_id):
        self._respond_friend_request(req_id, False, on_done=lambda r: (self._show_result(r), QTimer.singleShot(0, self.load)))

    def _respond_friend_request(self, req_id, accept, on_done=None):
        def job():
            cloud=self._cloud_social_service();record=db.get_friendship_record(req_id,self.user_id)
            if cloud and record.get("cloud_id"):
                cloud.respond_friend_request(record["cloud_id"],accept)
                return {"ok":True,"msg":tr("cloud_friend_accepted" if accept else "cloud_friend_rejected")}
            if cloud:raise RuntimeError(tr("cloud_friendship_not_synced"))
            return db.accept_friend_request(self.user_id,req_id) if accept else db.reject_friend_request(self.user_id,req_id)
        def ok(r):
            if on_done: on_done(r)
        self._run_cloud_job(job, on_ok=ok)

    def _show_result(self, r):
        if r["ok"]:
            SND.notify()
            _show(self, tr("berhasil_title"), r["msg"], "success")
        else:
            SND.error()
            _show(self, tr("gagal_title"), r["msg"], "error")

    def closeEvent(self, e):
        AppState.unregister(self.load)
        super().closeEvent(e)

# ══════════════════════════════════════════════════════════════════════════════
#  ChatDialog (Direct Messaging System with real-time updates)
# ══════════════════════════════════════════════════════════════════════════════
class ChatDialog(QDialog):
    """Offline-capable direct chat with cloud reply/edit/delete/reactions."""
    REACTIONS=("👍","❤️","😂","🎉","😮","😢")

    def __init__(self,user_id,friend_id,friend_name,parent=None):
        super().__init__(parent)
        self.user_id=user_id;self.friend_id=friend_id;self.friend_name=friend_name
        self.cloud_mode=False;self.cloud=None;self.cloud_conversation_id=None
        self.cloud_friend_id=(db.get_user(friend_id) or {}).get("cloud_user_id")
        self.page_limit=50;self.reply_target=None;self._loading=False;self.pending_attachment_ids=[]
        if db.get_cloud_user_link(user_id) and self.cloud_friend_id:
            try:
                from cloud_service import get_cloud_service
                self.cloud=get_cloud_service()
                if self.cloud.authenticated or self.cloud.restore_session(user_id):
                    self.cloud_conversation_id=str(self.cloud.get_or_create_direct_conversation(self.cloud_friend_id))
                    db.save_cloud_conversation(user_id,friend_id,self.cloud_conversation_id)
                    self.cloud_mode=True
            except Exception as error:log.warning(f"Cloud chat init gagal, memakai cache/local: {error}")
        self.setWindowTitle(tr("chat_with",name=friend_name));self.setMinimumSize(560,620);self.setStyleSheet(build_ss())
        self._build();self._load_messages()
        self.timer=QTimer(self);self.timer.timeout.connect(self._load_messages);self.timer.start(3000)
        self.typing_debounce=QTimer(self);self.typing_debounce.setSingleShot(True);self.typing_debounce.setInterval(500);self.typing_debounce.timeout.connect(self._send_typing_state)
        self.typing_clear=QTimer(self);self.typing_clear.setSingleShot(True);self.typing_clear.setInterval(4500);self.typing_clear.timeout.connect(lambda:self._set_typing(False))

    def _build(self):
        layout=QVBoxLayout(self);layout.setSpacing(8)
        top=QHBoxLayout()
        self.earlier_btn=_btn(tr("chat_load_earlier"),"diamond",self._load_earlier,30)
        top.addWidget(self.earlier_btn);top.addStretch();top.addWidget(_btn(tr("chat_clear_self"),"danger",self._clear_chat,30));layout.addLayout(top)
        self.chat_list=QListWidget();self.chat_list.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection)
        self.chat_list.itemDoubleClicked.connect(lambda _item:self._reply_selected());layout.addWidget(self.chat_list,1)
        actions=QHBoxLayout()
        actions.addWidget(_btn(tr("chat_reply"),"diamond",self._reply_selected,30))
        actions.addWidget(_btn(tr("chat_edit"),"solid",self._edit_selected,30))
        actions.addWidget(_btn(tr("chat_delete_message"),"danger",self._delete_selected,30))
        self.reaction_combo=QComboBox();self.reaction_combo.addItems(self.REACTIONS);actions.addWidget(self.reaction_combo)
        actions.addWidget(_btn(tr("chat_react"),"gold",self._react_selected,30))
        actions.addWidget(_btn(tr("chat_remove_reaction"),slot=lambda:self._react_selected(remove=True),h=30))
        actions.addWidget(_btn(tr("chat_download_attachment"),"diamond",self._download_selected_attachment,30))
        layout.addLayout(actions)
        self.attachment_label=_lbl("","sub",9);self.attachment_label.setWordWrap(True);self.attachment_label.setVisible(False);layout.addWidget(self.attachment_label)
        self.reply_label=_lbl("","sub",9);self.reply_label.setWordWrap(True);self.reply_label.setVisible(False);layout.addWidget(self.reply_label)
        self.typing_label=_lbl("","sub",9);layout.addWidget(self.typing_label)
        composer=QHBoxLayout();self.message_input=QLineEdit();self.message_input.setPlaceholderText(tr("chat_input_placeholder"))
        self.message_input.textChanged.connect(self._typing_changed);self.message_input.returnPressed.connect(self._send_message)
        composer.addWidget(_btn("📎","diamond",self._choose_attachments,34));composer.addWidget(self.message_input,1);composer.addWidget(_btn(tr("chat_send_btn"),"solid",self._send_message));layout.addLayout(composer)

    def _typing_changed(self,text):
        if self.cloud_mode:self.typing_debounce.start();self.typing_clear.start()

    def _send_typing_state(self):self._set_typing(bool(self.message_input.text().strip()))

    def _set_typing(self,state):
        if self.cloud_mode and self.cloud_conversation_id:
            try:self.cloud.set_conversation_typing(self.cloud_conversation_id,state)
            except Exception:pass

    def _selected_message(self):
        item=self.chat_list.currentItem();return item.data(Qt.ItemDataRole.UserRole) if item else None

    def _message_key(self,message):return str(message.get("cloud_id") if self.cloud_mode else message.get("id"))

    def _is_own(self,message):
        if self.cloud_mode:return message.get("sender_cloud_id")==((db.get_cloud_user_link(self.user_id) or {}).get("cloud_user_id"))
        return message.get("sender_id")==self.user_id

    @staticmethod
    def _reaction_text(reactions):
        counts={}
        for reaction in (reactions or {}).values():counts[reaction]=counts.get(reaction,0)+1
        return "  ".join(f"{emoji} {count}" for emoji,count in counts.items())

    def _render_messages(self,messages):
        selected=self._message_key(self._selected_message() or {})
        scroll=self.chat_list.verticalScrollBar();at_bottom=scroll.value()>=scroll.maximum()-4
        self.chat_list.clear();by_id={self._message_key(message):message for message in messages}
        for message in messages:
            own=self._is_own(message);sender=tr("chat_you") if own else tr("chat_friend")
            deleted=bool(message.get("deleted_at"));body=tr("chat_message_deleted") if deleted else (message.get("body") if self.cloud_mode else message.get("message")) or ""
            reply_id=message.get("reply_to_cloud_id") if self.cloud_mode else message.get("reply_to_id")
            reply_line=""
            if reply_id:
                target=by_id.get(str(reply_id));target_body=((target or {}).get("body") if self.cloud_mode else (target or {}).get("message")) or tr("chat_reply_unavailable")
                if (target or {}).get("deleted_at"):target_body=tr("chat_message_deleted")
                reply_line=f"↪ {target_body[:90]}\n"
            flags=[]
            if message.get("edited_at") and not deleted:flags.append(tr("chat_edited"))
            if message.get("sync_status")=="pending":flags.append(tr("chat_pending"))
            reaction_line=self._reaction_text(message.get("reactions"))
            suffix=(" · "+" · ".join(flags)) if flags else ""
            text=f"{sender} · {(message.get('created_at') or '')[11:16]}{suffix}\n{reply_line}{body}"
            for attachment in message.get("attachments") or []:
                text+=f"\n📎 {attachment.get('original_filename','attachment')} ({int(attachment.get('size_bytes') or 0)/1024:.1f} KB)"
            if reaction_line:text+=f"\n{reaction_line}"
            item=QListWidgetItem(text);item.setData(Qt.ItemDataRole.UserRole,message)
            image_attachment=next((a for a in message.get("attachments") or [] if a.get("thumbnail_data")),None)
            if image_attachment:
                pixmap=QPixmap();pixmap.loadFromData(bytes(image_attachment["thumbnail_data"]));item.setIcon(QIcon(pixmap))
            if own:item.setTextAlignment(Qt.AlignmentFlag.AlignRight)
            if deleted:item.setForeground(QColor(_T("muted")))
            self.chat_list.addItem(item)
            if self._message_key(message)==selected:self.chat_list.setCurrentItem(item)
        if at_bottom and self.chat_list.count():self.chat_list.scrollToBottom()

    def _refresh_cloud_page(self,before=None):
        remote=self.cloud.fetch_direct_messages(self.cloud_conversation_id,50,before)
        db.cache_cloud_messages(remote)
        ids=[row.get("id") for row in remote if row.get("id")]
        if ids:
            db.cache_cloud_message_reactions(self.cloud.fetch_message_reactions(ids),ids)
            try:db.cache_cloud_chat_attachments(self.user_id,self.cloud.fetch_message_attachments(ids))
            except Exception:pass
        return len(remote)

    def _load_messages(self):
        if self._loading:return
        self._loading=True
        try:
            if self.cloud_mode and self.cloud_conversation_id:
                def job():
                    if not (self.cloud.authenticated or self.cloud.restore_session(self.user_id)):
                        return None
                    self._refresh_cloud_page()
                    self.cloud.mark_conversation_read(self.cloud_conversation_id)
                    try:
                        typing=self.cloud.get_conversation_typing(self.cloud_conversation_id)
                    except Exception:
                        typing=[]
                    return typing
                def done(typing):
                    try:
                        db.mark_cloud_conversation_read_local(self.cloud_conversation_id)
                        messages=db.get_cached_cloud_messages(self.cloud_conversation_id,self.page_limit)
                        self._render_messages(messages)
                        if typing is not None:
                            current=(db.get_cloud_user_link(self.user_id) or {}).get("cloud_user_id")
                            self.typing_label.setText(tr("cloud_chat_typing") if any(row["user_id"]!=current for row in typing) else "")
                    finally:
                        self._loading=False
                def fail(_):
                    try:
                        messages=db.get_cached_cloud_messages(self.cloud_conversation_id,self.page_limit)
                        self._render_messages(messages)
                    except Exception:pass
                    self._loading=False
                run_in_thread(self,job,on_done=done,on_error=fail)
            else:
                messages=db.get_messages(self.user_id,self.friend_id,self.page_limit);self._render_messages(messages)
                db.mark_messages_read(self.user_id,self.friend_id)
                self._loading=False
        except Exception:
            self._loading=False

    def _load_earlier(self):
        if self.cloud_mode:
            cached=db.get_cached_cloud_messages(self.cloud_conversation_id,self.page_limit)
            oldest=next((m for m in cached if m.get("sync_status")!="pending"),None)
            def job():
                return self._refresh_cloud_page((oldest or {}).get("created_at")) if oldest else 0
            def done(count):
                self.page_limit+=max(50,count);self._load_messages()
            def err(error):
                _show(self,tr("gagal_title"),str(error),"error")
            run_in_thread(self,job,on_done=done,on_error=err)
        else:
            self.page_limit+=50
            self._load_messages()

    def _reply_selected(self):
        message=self._selected_message()
        if not message or message.get("deleted_at"):return
        key=self._message_key(message)
        if self.cloud_mode and key.startswith("pending:"):
            _show(self,tr("info_title"),tr("chat_pending_action_blocked"),"info");return
        self.reply_target=message
        body=(message.get("body") if self.cloud_mode else message.get("message")) or ""
        self.reply_label.setText(tr("chat_replying_to",message=body[:120]));self.reply_label.setVisible(True);self.message_input.setFocus()

    def _clear_reply(self):self.reply_target=None;self.reply_label.clear();self.reply_label.setVisible(False)

    def _edit_selected(self):
        message=self._selected_message()
        if not message or not self._is_own(message) or message.get("deleted_at"):return
        key=self._message_key(message)
        if self.cloud_mode and key.startswith("pending:"):_show(self,tr("info_title"),tr("chat_pending_action_blocked"),"info");return
        old=(message.get("body") if self.cloud_mode else message.get("message")) or ""
        value,ok=QInputDialog.getText(self,tr("chat_edit"),tr("chat_edit_prompt"),QLineEdit.EchoMode.Normal,old)
        if not ok or not value.strip() or value.strip()==old:return
        try:
            if self.cloud_mode:
                row=self.cloud.edit_direct_message(key,value.strip());db.cache_cloud_messages([row])
            else:db.edit_local_message(self.user_id,message["id"],value.strip())
            SND.click();self._load_messages()
        except Exception as error:_show(self,tr("gagal_title"),str(error),"error")

    def _delete_selected(self):
        message=self._selected_message()
        if not message or not self._is_own(message) or message.get("deleted_at"):return
        key=self._message_key(message)
        if self.cloud_mode and key.startswith("pending:"):_show(self,tr("info_title"),tr("chat_pending_action_blocked"),"info");return
        if QMessageBox.question(self,tr("confirm_title"),tr("chat_delete_confirm"),QMessageBox.StandardButton.Yes|QMessageBox.StandardButton.No)!=QMessageBox.StandardButton.Yes:return
        try:
            if self.cloud_mode:
                row=self.cloud.delete_direct_message(key);db.cache_cloud_messages([row]);db.cache_cloud_message_reactions([], [key])
            else:db.delete_local_message(self.user_id,message["id"])
            self._clear_reply();SND.click();self._load_messages()
        except Exception as error:_show(self,tr("gagal_title"),str(error),"error")

    def _react_selected(self,remove=False):
        message=self._selected_message()
        if not message or message.get("deleted_at"):return
        key=self._message_key(message)
        if self.cloud_mode and key.startswith("pending:"):_show(self,tr("info_title"),tr("chat_pending_action_blocked"),"info");return
        reaction=None if remove else self.reaction_combo.currentText()
        try:
            if self.cloud_mode:
                self.cloud.set_direct_message_reaction(key,reaction)
                db.cache_cloud_message_reactions(self.cloud.fetch_message_reactions([key]),[key])
            else:db.set_local_message_reaction(self.user_id,message["id"],reaction)
            SND.click();self._load_messages()
        except Exception as error:_show(self,tr("gagal_title"),str(error),"error")

    def _choose_attachments(self):
        remaining=5-len(self.pending_attachment_ids)
        if remaining<=0:_show(self,tr("info_title"),tr("chat_attachment_max"),"info");return
        paths,_=QFileDialog.getOpenFileNames(self,tr("chat_choose_attachment"),"",tr("chat_attachment_filter"))
        if not paths:return
        try:
            from cloud_service import get_cloud_service
            for path in paths[:remaining]:
                attachment=get_cloud_service().prepare_chat_attachment(self.user_id,path)
                self.pending_attachment_ids.append(attachment["id"])
            names=[db.get_chat_attachment(value).get("original_filename","") for value in self.pending_attachment_ids]
            self.attachment_label.setText(tr("chat_attachments_ready",files=", ".join(names)));self.attachment_label.setVisible(True)
        except Exception as error:_show(self,tr("gagal_title"),str(error),"error")

    def _clear_pending_attachments(self,delete=False):
        if delete:db.delete_pending_chat_attachments(self.user_id,self.pending_attachment_ids)
        self.pending_attachment_ids=[];self.attachment_label.clear();self.attachment_label.setVisible(False)

    def _download_selected_attachment(self):
        message=self._selected_message();attachments=(message or {}).get("attachments") or []
        if not attachments:return
        attachment=attachments[0]
        if len(attachments)>1:
            names=[item.get("original_filename","attachment") for item in attachments]
            selected,ok=QInputDialog.getItem(self,tr("chat_download_attachment"),tr("chat_choose_attachment"),names,0,False)
            if not ok:return
            attachment=attachments[names.index(selected)]
        raw=attachment.get("file_data")
        try:
            if raw is None and self.cloud_mode:raw=self.cloud.download_chat_attachment(self.user_id,attachment)
            if raw is None:raise RuntimeError(tr("chat_attachment_not_cached"))
            path,_=QFileDialog.getSaveFileName(self,tr("chat_download_attachment"),attachment.get("original_filename") or "attachment")
            if path:Path(path).write_bytes(bytes(raw));_show(self,tr("berhasil_title"),tr("chat_attachment_saved"),"success");self._load_messages()
        except Exception as error:_show(self,tr("gagal_title"),str(error),"error")

    def _clear_chat(self):
        if self.cloud_mode:_show(self,tr("info_title"),tr("cloud_chat_clear_local_only"),"info");return
        if QMessageBox.question(self,tr("confirm_title"),tr("chat_clear_confirm_self"),QMessageBox.StandardButton.Yes|QMessageBox.StandardButton.No)==QMessageBox.StandardButton.Yes:
            db.clear_friend_chat(self.user_id,self.friend_id);self._load_messages();SND.notify()

    def _send_message(self):
        msg=self.message_input.text().strip()
        if not msg and not self.pending_attachment_ids:return
        reply_id=self._message_key(self.reply_target) if self.reply_target else None
        display_body=msg or tr("chat_attachment_message")
        if self.cloud_mode and self.cloud_conversation_id:
            client_id=str(__import__('uuid').uuid4());current=(db.get_cloud_user_link(self.user_id) or {}).get("cloud_user_id")
            attachment_ids=list(self.pending_attachment_ids)
            def job():
                try:
                    if attachment_ids:
                        self.cloud.send_direct_message_with_attachments(self.user_id,self.cloud_conversation_id,msg,client_id,reply_id,attachment_ids)
                    else:
                        row=self.cloud.send_direct_message(self.cloud_conversation_id,msg,client_id,reply_id)
                        db.cache_cloud_messages([row])
                except Exception:
                    db.cache_pending_cloud_message(self.cloud_conversation_id,current,client_id,display_body,reply_id)
                    entity="direct_message_attachment" if attachment_ids else "direct_message"
                    payload={"conversation_id":self.cloud_conversation_id,"body":msg,"client_message_id":client_id,"reply_to_id":reply_id}
                    if attachment_ids:payload["attachment_local_ids"]=attachment_ids
                    db.enqueue_sync(self.user_id,entity,client_id,"send",payload)
                return True
            def done(_):
                self._set_typing(False);self.message_input.clear();self._clear_reply();self._clear_pending_attachments(False);self._load_messages()
            run_in_thread(self,job,on_done=done,on_error=lambda e: done(None))
        else:
            result=db.send_message(self.user_id,self.friend_id,display_body,TimeSync.get_current_time().isoformat(),int(reply_id) if reply_id else None)
            if self.pending_attachment_ids:db.link_local_chat_attachments(self.user_id,result.get("message_id"),self.pending_attachment_ids)
            self._set_typing(False);self.message_input.clear();self._clear_reply();self._clear_pending_attachments(False);self._load_messages()

    def closeEvent(self,e):
        self.timer.stop();self.typing_debounce.stop();self.typing_clear.stop();self._set_typing(False);self._clear_pending_attachments(True);super().closeEvent(e)


# ══════════════════════════════════════════════════════════════════════════════
#  GuildChatDialog (Direct Messaging Guild System with real-time updates)
# ══════════════════════════════════════════════════════════════════════════════
class GuildChatDialog(QDialog):
    def __init__(self, guild_id, user_id, parent=None):
        super().__init__(parent)

        self.guild_id = guild_id
        self.user_id = user_id
        conn = db.get_conn()
        leader_row = conn.execute("SELECT leader_id FROM guilds WHERE id=?", (guild_id,)).fetchone()
        self.is_leader = leader_row and leader_row["leader_id"] == user_id
        conn.close()
        self.setWindowTitle(tr("guild_chat_title"))
        self.setMinimumSize(450, 550)
        self.setStyleSheet(build_ss())
        self._build()
        self._load_messages()
        self.timer = QTimer()
        self.timer.timeout.connect(self._load_messages)
        self.timer.start(3000)

    def _build(self):
        layout = QVBoxLayout(self)

        # Tombol Clear All jika leader
        if self.is_leader:
            btn_layout = QHBoxLayout()
            clear_all_btn = _btn(tr("chat_clear_all"), "danger", self._clear_all, 32)
            btn_layout.addStretch()
            btn_layout.addWidget(clear_all_btn)
            layout.addLayout(btn_layout)

        self.chat_area = QTextEdit()
        self.chat_area.setReadOnly(True)
        layout.addWidget(self.chat_area)

        input_layout = QHBoxLayout()
        self.message_input = QLineEdit()
        send_btn = _btn(tr("chat_send_btn"), "solid", self._send_message)
        input_layout.addWidget(self.message_input)
        input_layout.addWidget(send_btn)
        layout.addLayout(input_layout)

    def _clear_all(self):
        reply = QMessageBox.question(self, tr("confirm_title"), tr("chat_clear_all_confirm"),
                                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        if reply == QMessageBox.StandardButton.Yes:
            db.clear_guild_chat(self.guild_id)
            self._load_messages()
            SND.notify()

    def _load_messages(self):
        msgs = db.get_guild_messages(self.guild_id)
        self.chat_area.clear()
        for m in msgs:
            self.chat_area.append(tr("guild_chat_message_format", time=m['created_at'][11:16], name=m['display_name'], message=m['message']))

    def _send_message(self):
        msg = self.message_input.text().strip()
        if msg:
            server_now = TimeSync.get_current_time().isoformat()
            db.send_guild_message(self.guild_id, self.user_id, msg, server_now)
            self.message_input.clear()
            self._load_messages()

    def closeEvent(self, e):
        self.timer.stop()
        super().closeEvent(e)

class CloudGuildChatDialog(QDialog):
    REACTIONS=("👍","❤️","😂","🎉","⚔️","🔥")
    def __init__(self,cloud,guild_id,parent=None):
        super().__init__(parent);self.cloud=cloud;self.guild_id=guild_id;self.page_limit=50;self.reply_target=None
        self.current=cloud.current_cloud_user_id;members=cloud.get_online_guild_members();mine=next((m for m in members if m["guild_id"]==guild_id and m["user_id"]==self.current),{})
        self.can_manage=mine.get("role") in ("leader","officer")
        self.setWindowTitle(tr("guild_chat_title"));self.setMinimumSize(560,620);self.setStyleSheet(build_ss())
        layout=QVBoxLayout(self);top=QHBoxLayout();top.addWidget(_btn(tr("chat_load_earlier"),"diamond",self._older,30));top.addStretch();layout.addLayout(top)
        self.list=QListWidget();self.list.itemDoubleClicked.connect(lambda _:self._reply());layout.addWidget(self.list,1)
        actions=QHBoxLayout();actions.addWidget(_btn(tr("chat_reply"),"diamond",self._reply,28));actions.addWidget(_btn(tr("chat_edit"),"solid",self._edit,28));actions.addWidget(_btn(tr("chat_delete_message"),"danger",self._delete,28));self.reaction=QComboBox();self.reaction.addItems(self.REACTIONS);actions.addWidget(self.reaction);actions.addWidget(_btn(tr("chat_react"),"gold",self._react,28));actions.addWidget(_btn(tr("chat_remove_reaction"),slot=lambda:self._react(True),h=28));layout.addLayout(actions)
        self.reply_label=_lbl("","sub",9);self.reply_label.setVisible(False);layout.addWidget(self.reply_label)
        row=QHBoxLayout();self.input=QLineEdit();self.input.returnPressed.connect(self._send);row.addWidget(self.input,1);row.addWidget(_btn(tr("chat_send_btn"),"solid",self._send,34));layout.addLayout(row)
        self.timer=QTimer(self);self.timer.timeout.connect(self._load);self.timer.start(2500);self._load()
    def _selected(self):
        item=self.list.currentItem();return item.data(Qt.ItemDataRole.UserRole) if item else None
    def _fetch(self,before=None):
        rows=self.cloud.get_online_guild_messages(self.guild_id,50,before);db.cache_cloud_guild_messages(rows);ids=[r["id"] for r in rows]
        if ids:db.cache_cloud_guild_reactions(self.cloud.get_online_guild_message_reactions(ids),ids)
        return len(rows)
    def _load(self):
        try:self._fetch();self.cloud.mark_online_guild_read(self.guild_id)
        except Exception:pass
        messages=db.get_cached_cloud_guild_messages(self.guild_id,self.page_limit);by_id={m["cloud_id"]:m for m in messages};self.list.clear()
        for message in messages:
            deleted=bool(message.get("deleted_at"));body=tr("chat_message_deleted") if deleted else message.get("body") or ""
            reply="";target=by_id.get(str(message.get("reply_to_cloud_id")))
            if message.get("reply_to_cloud_id"):reply=f"↪ {((target or {}).get('body') or tr('chat_reply_unavailable'))[:80]}\n"
            reactions=ChatDialog._reaction_text(message.get("reactions"));flags=tr("chat_edited") if message.get("edited_at") and not deleted else ""
            text=f"{message['sender_cloud_id'][:8]} · {(message.get('created_at') or '')[11:16]} {flags}\n{reply}{body}"+(f"\n{reactions}" if reactions else "")
            item=QListWidgetItem(text);item.setData(Qt.ItemDataRole.UserRole,message)
            if message["sender_cloud_id"]==self.current:item.setTextAlignment(Qt.AlignmentFlag.AlignRight)
            self.list.addItem(item)
        if self.list.count():self.list.scrollToBottom()
    def _older(self):
        cached=db.get_cached_cloud_guild_messages(self.guild_id,self.page_limit);oldest=cached[0] if cached else None
        try:self._fetch((oldest or {}).get("created_at"));self.page_limit+=50;self._load()
        except Exception as error:_show(self,tr("gagal_title"),str(error),"error")
    def _reply(self):
        msg=self._selected()
        if msg and not msg.get("deleted_at"):self.reply_target=msg;self.reply_label.setText(tr("chat_replying_to",message=(msg.get("body") or "")[:100]));self.reply_label.setVisible(True)
    def _edit(self):
        msg=self._selected()
        if not msg or msg["sender_cloud_id"]!=self.current or msg.get("deleted_at"):return
        value,ok=QInputDialog.getText(self,tr("chat_edit"),tr("chat_edit_prompt"),QLineEdit.EchoMode.Normal,msg.get("body") or "")
        if ok and value.strip():
            try:db.cache_cloud_guild_messages([self.cloud.edit_online_guild_message(msg["cloud_id"],value)]);self._load()
            except Exception as error:_show(self,tr("gagal_title"),str(error),"error")
    def _delete(self):
        msg=self._selected()
        if not msg or (msg["sender_cloud_id"]!=self.current and not self.can_manage):return
        if QMessageBox.question(self,tr("confirm_title"),tr("chat_delete_confirm"),QMessageBox.StandardButton.Yes|QMessageBox.StandardButton.No)!=QMessageBox.StandardButton.Yes:return
        try:db.cache_cloud_guild_messages([self.cloud.delete_online_guild_message(msg["cloud_id"])]);self._load()
        except Exception as error:_show(self,tr("gagal_title"),str(error),"error")
    def _react(self,remove=False):
        msg=self._selected()
        if not msg or msg.get("deleted_at"):return
        try:self.cloud.set_online_guild_message_reaction(msg["cloud_id"],None if remove else self.reaction.currentText());db.cache_cloud_guild_reactions(self.cloud.get_online_guild_message_reactions([msg["cloud_id"]]),[msg["cloud_id"]]);self._load()
        except Exception as error:_show(self,tr("gagal_title"),str(error),"error")
    def _send(self):
        body=self.input.text().strip()
        if not body:return
        try:row=self.cloud.send_online_guild_message(self.guild_id,body,reply_to_id=(self.reply_target or {}).get("cloud_id"));db.cache_cloud_guild_messages([row]);self.input.clear();self.reply_target=None;self.reply_label.setVisible(False);self._load()
        except Exception as error:_show(self,tr("gagal_title"),str(error),"error")
    def closeEvent(self,event):self.timer.stop();super().closeEvent(event)


# ══════════════════════════════════════════════════════════════════════════════
#  FriendProfileDialog
# ══════════════════════════════════════════════════════════════════════════════
class FriendProfileDialog(QDialog):
    def __init__(self, friend_id, parent=None):
        super().__init__(parent)

        self.friend_id = friend_id
        self.setWindowTitle(tr("friend_profile_title"))
        self.setMinimumSize(400, 500)
        self.setStyleSheet(build_ss())
        self._build()
        self._load()

    def _build(self):
        layout = QVBoxLayout(self)
        self.content = QWidget()
        self.content_layout = QVBoxLayout(self.content)
        scroll = _scrolled(self.content)
        layout.addWidget(scroll)

    def _load(self):
        while self.content_layout.count():
            item = self.content_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
        d = db.get_friend_profile_details(self.friend_id)
        if not d:
            return
        u = d["user"]
        stats = d["stats"]

        # ── Header: avatar + identitas ──
        avatar = _user_photo_label(u, 96)
        self.content_layout.addWidget(avatar, 0, Qt.AlignmentFlag.AlignHCenter)
        name_lbl = _lbl(u.get("display_name", "No name"), size=16, bold=True)
        name_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.content_layout.addWidget(name_lbl)
        user_lbl = _lbl(f"@{u.get('username', '')}", "sub")
        user_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.content_layout.addWidget(user_lbl)
        relation = db.get_couple_status_between(AppState.user_id, self.friend_id)
        if relation.get("status") in ("accepted", "pending"):
            relation_lbl = _lbl(
                tr("couple_status_couple") if relation.get("status") == "accepted" else tr("couple_status_pending"),
                "sub", 10)
            relation_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
            self.content_layout.addWidget(relation_lbl)

        # Chips: level + kelas + title
        chips = QHBoxLayout()
        chips.setSpacing(8)
        chips.addStretch()
        lvl_chip = QLabel(f"⚔️ Lv {d['level']}")
        lvl_chip.setStyleSheet(f"color:#f0c040; font-weight:bold; font-size:12px; "
                               f"background:{_T('panel')}; border:1px solid {_T('border')}; "
                               f"border-radius:10px; padding:3px 10px;")
        chips.addWidget(lvl_chip)
        if d["avatar_class"]:
            cls_txt = tr(f"class_{d['avatar_class']}_name")
            cls_chip = QLabel(f"🎭 {cls_txt}")
            cls_chip.setStyleSheet(f"color:{_T('text')}; font-size:12px; background:{_T('panel')}; "
                                   f"border:1px solid {_T('border')}; border-radius:10px; padding:3px 10px;")
            chips.addWidget(cls_chip)
        if d["selected_title"]:
            t_chip = QLabel(f"🏅 {d['selected_title']}")
            t_chip.setStyleSheet(f"color:#4dd9e0; font-size:12px; font-weight:bold; background:{_T('panel')}; "
                                 f"border:1px solid {_T('border')}; border-radius:10px; padding:3px 10px;")
            chips.addWidget(t_chip)
        chips.addStretch()
        self.content_layout.addLayout(chips)

        # Info ringkas: bio, guild, rebirth, sport level, join date
        info_card = _card()
        iv = QVBoxLayout(info_card)
        if u.get("bio"):
            bio = QLabel(f"💬 {u['bio']}")
            bio.setWordWrap(True)
            bio.setStyleSheet(f"color:{_T('muted')}; font-style:italic;")
            iv.addWidget(bio)
        if d["guild_name"]:
            iv.addWidget(QLabel(tr("friend_guild", name=d["guild_name"])))
        mini = []
        mini.append(tr("friend_sport_level", lvl=d["sport_level"]))
        mini.append(tr("friend_rebirth", count=d["rebirth_count"]))
        if d["join_date"]:
            mini.append(tr("friend_joined", date=d["join_date"]))
        ml = QLabel("   ·   ".join(mini))
        ml.setStyleSheet(f"color:{_T('muted')}; font-size:11px;")
        ml.setWordWrap(True)
        iv.addWidget(ml)
        self.content_layout.addWidget(info_card)

        # ── Progres XP ──
        self.content_layout.addWidget(_lbl(tr("friend_xp_progress"), "sub", 11))
        xpbar = QProgressBar()
        xpbar.setRange(0, max(1, d["xp_needed"]))
        xpbar.setValue(min(d["xp"], d["xp_needed"]))
        xpbar.setFormat(f"{d['xp']}/{d['xp_needed']} XP  (" + tr("friend_total_xp") +
                        f": {int(d['total_xp_earned'])} )")
        xpbar.setMinimumHeight(18)
        self.content_layout.addWidget(xpbar)

        # ── Progres achievement ──
        self.content_layout.addWidget(_lbl(
            tr("friend_achievements_progress", done=d["achievements_done"],
               total=d["achievements_total"]), "sub", 11))
        abar = QProgressBar()
        abar.setRange(0, max(1, d["achievements_total"]))
        abar.setValue(d["achievements_done"])
        abar.setFormat(f"{d['achievements_done']}/{d['achievements_total']}")
        abar.setMinimumHeight(18)
        self.content_layout.addWidget(abar)

        # 6 achievement terbaru
        if d["latest_achievements"]:
            self.content_layout.addWidget(_lbl(tr("friend_latest_achievements"), "sub", 11))
            grid_w = QWidget()
            grid = QGridLayout(grid_w)
            grid.setContentsMargins(0, 0, 0, 0)
            grid.setSpacing(6)
            lang = AppState.get_language()
            for i, ach in enumerate(d["latest_achievements"]):
                chip = QFrame()
                chip.setStyleSheet(f"background:{_T('panel')}; border:1px solid {_T('border')}; border-radius:8px;")
                ch = QHBoxLayout(chip)
                ch.setContentsMargins(8, 4, 8, 4)
                ch.addWidget(_emoji_label(ach["icon"], ICON_INLINE))
                ach_name, _ = db.tr_achievement(ach, lang)
                nm = QLabel(ach_name)
                nm.setStyleSheet("font-size:11px;")
                nm.setWordWrap(True)
                ch.addWidget(nm, 1)
                grid.addWidget(chip, i // 2, i % 2)
            self.content_layout.addWidget(grid_w)

        # ── Statistik detail ──
        self.content_layout.addWidget(_lbl(tr("friend_stats_title"), "sub", 11))
        data = [
            (tr("stats_habit_today"), f"{stats['habits_done_today']}/{stats['habits_total']}"),
            (tr("stats_daily_today"), f"{stats['dailies_done_today']}/{stats['dailies_total']}"),
            (tr("stats_quest_done"), f"{stats['todos_done']}/{stats['todos_total']}"),
            (tr("friend_tasks_done"), str(d["tasks_done"])),
            (tr("stats_max_streak"), str(stats["max_streak"])),
            (tr("stats_boss_killed"), str(stats["bosses_killed"])),
            (tr("stats_pets"), str(stats["pet_count"])),
            (tr("friend_pomodoro"), f"{d['pomodoro_minutes']} min"),
        ]
        grid2_w = QWidget()
        grid2 = QGridLayout(grid2_w)
        grid2.setContentsMargins(0, 0, 0, 0)
        grid2.setSpacing(6)
        for i, (label, value) in enumerate(data):
            cell = QFrame()
            cell.setStyleSheet(f"background:{_T('panel')}; border:1px solid {_T('border')}; border-radius:8px;")
            cv = QVBoxLayout(cell)
            cv.setContentsMargins(10, 6, 10, 6)
            cv.setSpacing(2)
            vl = QLabel(value)
            vl.setStyleSheet(f"color:{_T('text')}; font-size:14px; font-weight:bold;")
            ll = QLabel(label)
            ll.setStyleSheet(f"color:{_T('muted')}; font-size:10px;")
            ll.setWordWrap(True)
            cv.addWidget(vl)
            cv.addWidget(ll)
            grid2.addWidget(cell, i // 2, i % 2)
        self.content_layout.addWidget(grid2_w)
        self.content_layout.addStretch()


# ══════════════════════════════════════════════════════════════════════════════
#  Reset Password via Pertanyaan Keamanan
# ══════════════════════════════════════════════════════════════════════════════
class ResetPasswordBySecurityDialog(QDialog):
    def __init__(self, parent=None):
        super().__init__(parent)

        self.setWindowTitle(tr("reset_password_security_title"))
        self.setMinimumSize(450, 400)
        self.setStyleSheet(build_overworld_ss())
        self.user_id = None
        self.security_question = None
        self._build()

    def _build(self):
        layout = QVBoxLayout(self)
        layout.setSpacing(12)

        self.step = 1  # 1: username, 2: jawaban, 3: reset
        self._step1()

    def _step1(self):
        self._clear()
        layout = self.layout()
        layout.addWidget(_lbl(tr("reset_password_username"), size=12))
        self.username_input = _input(tr("login_username"))
        layout.addWidget(self.username_input)
        btn = _btn(tr("reset_password_check"), "solid", self._check_username)
        layout.addWidget(btn)
        self.msg_label = _lbl("", "sub", 12)
        layout.addWidget(self.msg_label)

    def _check_username(self):
        username = self.username_input.text().strip()
        if not username:
            self.msg_label.setText(tr("reset_username_empty"))
            return
        conn = db.get_conn()
        row = conn.execute(
            "SELECT id, security_question FROM users WHERE username=?",
            (username.lower(),)
        ).fetchone()
        conn.close()
        if not row:
            self.msg_label.setText(tr("reset_username_notfound"))
            return
        if not row["security_question"]:
            self.msg_label.setText(tr("reset_no_sq"))
            return
        self.user_id = row["id"]
        self.security_question = row["security_question"]
        self._step2()

    def _step2(self):
        self._clear()
        layout = self.layout()
        layout.addWidget(_lbl(tr("reset_password_security_question"), size=12))
        layout.addWidget(_lbl(self.security_question, size=12, bold=True))
        self.answer_input = _input(tr("reset_password_answer"))
        layout.addWidget(self.answer_input)
        btn = _btn(tr("reset_password_verify"), "solid", self._verify)

        layout.addWidget(btn)
        self.msg_label = _lbl("", "sub", 12)
        layout.addWidget(self.msg_label)

    def _verify(self):
        answer = self.answer_input.text().strip()
        if not answer:
            self.msg_label.setText(tr("reset_answer_empty"))
            return
        if db.verify_security_answer(self.user_id, answer):
            self._step3()
        else:
            self.msg_label.setText(tr("reset_answer_wrong"))

    def _step3(self):
        self._clear()
        if not self.user_id:
            self.msg_label.setText(tr("reset_error"))
            return
        layout = self.layout()
        layout.addWidget(_lbl(tr("reset_password_new"), size=12))
        self.new_pass = _input(tr("reset_password_new"), password=True)
        self.confirm_pass = _input(tr("reset_password_confirm"), password=True)
        layout.addWidget(self.new_pass)
        layout.addWidget(self.confirm_pass)
        btn = _btn(tr("reset_password_btn"), "solid", self._reset)
        layout.addWidget(btn)
        self.msg_label = _lbl("", "sub", 12)
        layout.addWidget(self.msg_label)

    def _reset(self):
        p1 = self.new_pass.text()
        p2 = self.confirm_pass.text()
        if len(p1) < db.PASSWORD_MIN_LEN:
            self.msg_label.setText(tr("login_pw_min"))
            return
        if p1 != p2:
            self.msg_label.setText(tr("login_pw_mismatch"))
            return
        r = db.reset_password_by_security(self.user_id, p1)
        if r["ok"]:
            _show(self, tr("berhasil_title"), tr("reset_success_msg"), "success")
            self.accept()
        else:
            self.msg_label.setText(r["msg"])

    def _clear(self):
        # Hapus semua widget dari layout
        layout = self.layout()
        while layout.count():
            item = layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()

# ══════════════════════════════════════════════════════════════════════════════
#  LOGIN WINDOW  (complex & user-friendly — no fade_in on self)
# ══════════════════════════════════════════════════════════════════════════════
class LoginWindow(QDialog):
    logged_in = pyqtSignal(dict)

    def __init__(self):
        super().__init__()
        self.setWindowTitle(tr("login_title"))
        self.setMinimumSize(500, 620)
        self.setWindowIcon(QIcon(get_icon_path('craftlife.ico')))
        self.setStyleSheet(build_ss())
        self._build()
        # Sembunyikan dulu, cek session
        self.hide()
        from PyQt6.QtCore import QTimer
        QTimer.singleShot(10, self._check_auto_login)

    def _check_auto_login(self):
        session = load_session()
        if session:
            user = db.get_user(session["user_id"])
            if user:
                self.logged_in.emit(user)
                self.accept()
                return
        self.show()

    def _build(self):
        root = QVBoxLayout(self)
        root.setContentsMargins(0, 0, 0, 0)
        root.setSpacing(0)

        # Banner (plain widget, safe to fade_in)
        banner = QWidget()
        banner.setMinimumHeight(110)
        banner.setStyleSheet(
            f"background: qlineargradient(x1:0,y1:0,x2:1,y2:1,"
            f"stop:0 {_T('bg')},stop:1 {_T('panel')});"
            f"border-bottom: 2px solid {_T('primary')};")
        bl = QVBoxLayout(banner)
        bl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        t1 = _lbl(tr("app_logo"), size=24, bold=True)
        t1.setAlignment(Qt.AlignmentFlag.AlignCenter)
        t1.setStyleSheet(f"color: {_T('light')};")
        t2 = _lbl(tr("app_tagline"), size=12)
        t2.setAlignment(Qt.AlignmentFlag.AlignCenter)
        bl.addWidget(t1)
        bl.addWidget(t2)
        root.addWidget(banner)
        fade_in(banner, 300)   # fade on banner widget — safe

        body = QWidget()
        body_lay = QVBoxLayout(body)
        body_lay.setContentsMargins(40, 20, 40, 20)
        body_lay.setSpacing(12)

        tabs = QTabWidget()
        tabs.addTab(self._login_tab(),    tr("login_tab_login_label"))
        tabs.addTab(self._register_tab(), tr("login_tab_register_label"))
        body_lay.addWidget(tabs)
        root.addWidget(body)

    def _login_tab(self) -> QWidget:
        w   = QWidget()
        lay = QVBoxLayout(w)
        lay.setContentsMargins(0, 16, 0, 0)
        lay.setSpacing(12)

        self._l_user = _input(tr("login_username"))
        self._l_pass = _input(tr("login_password"), True)
        self._l_msg  = _lbl("", "sub", 12)
        self._l_msg.setStyleSheet("color: #e05050;")
        self._l_msg.setWordWrap(True)

        self._remember_cb = QCheckBox(tr("login_remember_text"))
        self._remember_cb.setStyleSheet(f"color: {_T('text')};")
        lay.addWidget(self._remember_cb)

        ok = _btn(tr("login_button_text"), "solid", self._do_login, 48)
        for w_ in [self._l_user, self._l_pass, ok, self._l_msg]:
            lay.addWidget(w_)
        lay.addStretch()

        forgot_btn = _btn(tr("login_forgot_btn"), "flat", self._forgot_password)
        lay.addWidget(forgot_btn)
        self._l_pass.returnPressed.connect(self._do_login)
        self._l_user.returnPressed.connect(self._l_pass.setFocus)
        return w

    def _forgot_password(self):
        dlg = ChooseResetMethodDialog(self)
        dlg.exec()

    def _register_tab(self) -> QWidget:
        w   = QWidget()
        lay = QVBoxLayout(w)
        lay.setContentsMargins(0, 16, 0, 0)
        lay.setSpacing(10)

        self._r_user  = _input(tr("register_username"))
        self._r_disp  = _input(tr("register_display"))
        self._r_pass = _input(tr("register_password"), True)
        self._r_pass2 = _input(tr("register_confirm"), True)
        self._r_bio   = _input(tr("register_bio"))

        lay.addWidget(_lbl(tr("register_class_label"), size=12))
        self._r_class = QComboBox()
        self._r_class.setMinimumHeight(42)
        for cid, cdata in db.AVATAR_CLASSES.items():
            from translations import TRANSLATIONS
            # Ambil terjemahan nama class dan bonus
            name_key = f"class_{cid}_name"
            bonus_key = f"class_{cid}_bonus"
            name_text = tr(name_key) if name_key in TRANSLATIONS else cdata['name']
            bonus_text = tr(bonus_key) if bonus_key in TRANSLATIONS else cdata['bonus']
            self._r_class.addItem(
                f"{cdata['icon']}  {name_text}  —  {bonus_text}",
                cid)

        self._r_msg = _lbl("", "sub", 12)
        self._r_msg.setWordWrap(True)

        # Indikator kekuatan password (live mengikuti ketikan)
        self._r_meter = PasswordStrengthMeter(self._r_pass)

        ok = _btn(tr("register_button_text"), "solid", self._do_register, 48)
        for w_ in [self._r_user, self._r_disp, self._r_pass,
                   self._r_pass2, self._r_meter, self._r_bio, self._r_class,
                   ok, self._r_msg]:
            lay.addWidget(w_)
        lay.addStretch()
        return w

    def _do_login(self):
        loading = LoadingDialog(tr("login_processing"), self)
        loading.show()
        QApplication.processEvents()

        try:
            r = db.login_user(self._l_user.text(), self._l_pass.text())
            if r["ok"]:
                SND.complete()
                if self._remember_cb.isChecked():
                    user = r["user"]
                    save_session(user["id"], user["username"])
                loading.accept()
                self.logged_in.emit(r["user"])
                self.accept()
            else:
                loading.accept()
                SND.error()
                self._l_msg.setText(r["msg"])
        except Exception as e:
            loading.accept()
            self._l_msg.setText(tr("error_occurred", error=e))

    def _do_register(self):
        u = self._r_user.text().strip()
        if not u or " " in u:
            self._r_msg.setStyleSheet("color:#e05050;")
            self._r_msg.setText(tr("register_username_invalid"))
            return
        if len(self._r_pass.text()) < db.PASSWORD_MIN_LEN:
            self._r_msg.setStyleSheet("color:#e05050;")
            self._r_msg.setText(tr("login_pw_min"))
            return
        if self._r_pass.text() != self._r_pass2.text():
            self._r_msg.setStyleSheet("color:#e05050;")
            self._r_msg.setText(tr("login_pw_mismatch"))
            return
        r = db.register_user(
            u, self._r_pass.text(),
            self._r_disp.text().strip(),
            self._r_bio.text(),
            self._r_class.currentData(),
        )
        if r["ok"]:
            SND.level_up()
            self._r_msg.setStyleSheet(f"color:{_T('light')};")
            self._r_msg.setText("✅ " + r["msg"] + tr("register_success_login_now"))
        else:
            SND.error()
            self._r_msg.setStyleSheet("color:#e05050;")
            self._r_msg.setText(r["msg"])


# ══════════════════════════════════════════════════════════════════════════════
#  PASSWORD STRENGTH METER ─ indikator kekuatan password (live)
# ══════════════════════════════════════════════════════════════════════════════
def _password_score(pw: str) -> int:
    """Skor kekuatan password 0..4 (0 = sangat lemah)."""
    if not pw:
        return 0
    score = 0
    if len(pw) >= 8:
        score += 1
    if len(pw) >= 12:
        score += 1
    kinds = sum(bool(re.search(p, pw))
                for p in (r"[a-z]", r"[A-Z]", r"\d", r"[^A-Za-z0-9]"))
    if kinds >= 2:
        score += 1
    if kinds >= 3:
        score += 1
    if kinds == 4 and len(pw) >= 10:
        score += 1
    return min(score, 4)


class PasswordStrengthMeter(QWidget):
    """Bar 4 segmen + label — update otomatis mengikuti input password."""

    _LEVELS = [
        ("pw_strength_very_weak", "#e05050"),
        ("pw_strength_weak",      "#e08050"),
        ("pw_strength_fair",      "#e0b050"),
        ("pw_strength_strong",    "#7ac74c"),
        ("pw_strength_very_strong", "#4caf7d"),
    ]

    def __init__(self, password_input, parent=None):
        super().__init__(parent)
        lay = QHBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(8)

        bar_row = QHBoxLayout()
        bar_row.setSpacing(3)
        self._bars = []
        for _ in range(4):
            seg = QFrame()
            seg.setFixedHeight(5)
            seg.setMinimumWidth(26)
            seg.setStyleSheet(f"background:{_T('border')}; border-radius:2px;")
            self._bars.append(seg)
            bar_row.addWidget(seg)
        bar_row.addStretch()

        self._lbl = QLabel()
        self._lbl.setStyleSheet(f"color:{_T('sub')}; font-size:11px;")

        lay.addLayout(bar_row, 1)
        lay.addWidget(self._lbl)

        password_input.textChanged.connect(self.update_strength)
        self.update_strength(password_input.text())

    def update_strength(self, pw: str):
        score = _password_score(pw)
        key, color = self._LEVELS[score]
        for i, seg in enumerate(self._bars):
            c = color if i < score else _T("border")
            seg.setStyleSheet(f"background:{c}; border-radius:2px;")
        self._lbl.setText(tr(key) if pw else tr("pw_strength_hint"))
        self._lbl.setStyleSheet(
            f"color:{color if pw else _T('sub')}; font-size:11px;")


