from PyQt6.QtCore import QObject, QThread


class _LearningTaskWorker(QObject):
    """Run one Learning operation without blocking the Qt UI thread."""
    succeeded = pyqtSignal(int, object)
    failed = pyqtSignal(int, str)

    def __init__(self, job_id, callback):
        super().__init__()
        self.job_id = job_id
        self.callback = callback

    def run(self):
        try:
            self.succeeded.emit(self.job_id, self.callback())
        except Exception as error:
            self.failed.emit(self.job_id, str(error))


class _LearningChatInput(QTextEdit):
    """Multiline chat composer: Enter sends, Shift+Enter inserts a newline."""
    submit_requested = pyqtSignal()

    def keyPressEvent(self, event):
        if (event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter)
                and not (event.modifiers() & Qt.KeyboardModifier.ShiftModifier)):
            event.accept()
            self.submit_requested.emit()
            return
        super().keyPressEvent(event)


