        ("faq", "learning_studio_faq"),
        ("mind_map", "learning_studio_mindmap"),
        ("timeline", "learning_studio_timeline"),
        ("quiz", "learning_studio_quiz"),
        ("audio_overview", "learning_studio_podcast_script"),
