class _SupplyItemDialog(QDialog):
    def __init__(self, item=None, parent=None):
        super().__init__(parent)
        self.setWindowTitle(tr("supplies_dlg_title_edit") if item else tr("supplies_dlg_title_add"))
        self.setMinimumWidth(440)
        lay = QVBoxLayout(self); lay.setSpacing(8)
        self.name = _input(tr("supplies_name_ph")); lay.addWidget(self.name)
        r1 = QHBoxLayout()
        self.category = _input(tr("supplies_category_ph")); r1.addWidget(self.category, 1)
        self.unit = _input(tr("supplies_unit_ph")); self.unit.setFixedWidth(90); r1.addWidget(self.unit)
        lay.addLayout(r1)
        r2 = QHBoxLayout()
        self.stock = _input("0"); self.minstock = _input("0"); self.price = _input("0")
        for w, lbl in ((self.stock, tr("supplies_stock_lbl")), (self.minstock, tr("supplies_min_lbl")), (self.price, tr("supplies_price_lbl"))):
            col = QVBoxLayout(); col.addWidget(_lbl(lbl, "sub", 10)); col.addWidget(w); r2.addLayout(col)
        lay.addLayout(r2)
        self.location = _input(tr("supplies_location_ph")); lay.addWidget(self.location)
        self.notes = _input(tr("supplies_notes_ph")); lay.addWidget(self.notes)
        self.econ_cat = QComboBox(); self.econ_cat.setEditable(True)
        self.econ_cat.addItem("Supplies")
        lay.addWidget(_lbl(tr("supplies_economy_lbl"), "sub", 10)); lay.addWidget(self.econ_cat)
        lay.addWidget(_btn(tr("btn_save"), "solid", self.accept, 36))
        if item:
            self.name.setText(item["name"]); self.category.setText(item["category"] or "")
            self.unit.setText(item["unit"] or "pcs"); self.stock.setText(str(item["stock"]))
            self.minstock.setText(str(item["min_stock"])); self.price.setText(str(item["price"]))
            self.location.setText(item["location"] or ""); self.notes.setText(item["notes"] or "")
            if item.get("economy_category"):
                self.econ_cat.setEditText(item["economy_category"])
            self.stock.setEnabled(False)  # stok setelah awal hanya berubah via transaksi

    def values(self):
        def f(w):
            try:
                return float((w.text() or "0").replace(",", "."))
            except ValueError:
                return 0.0
        return {"name": self.name.text().strip(), "category": self.category.text().strip(),
                "unit": self.unit.text().strip() or "pcs", "stock": f(self.stock), "min_stock": f(self.minstock),
                "price": f(self.price), "location": self.location.text().strip(), "notes": self.notes.text().strip(),
                "economy_category": self.econ_cat.currentText().strip()}


class _SupplyTxDialog(QDialog):
    def __init__(self, item, parent=None):
        super().__init__(parent)
        self.setWindowTitle(f"{tr('supplies_tx_title')} — {item['name']}")
        self.setMinimumWidth(380)
        lay = QVBoxLayout(self); lay.setSpacing(8)
        lay.addWidget(_lbl(tr("supplies_stock_now", stock=self._fmt(item["stock"]), unit=item["unit"] or "pcs"), "sub", 11))
        self.kind = QComboBox()
        for label_key, value in (("supplies_tx_in", "in"), ("supplies_tx_out", "out"), ("supplies_tx_adjust", "adjust")):
            self.kind.addItem(tr(label_key), value)
        lay.addWidget(self.kind)
        self.qty = _input("0"); lay.addWidget(_lbl(tr("supplies_qty_lbl"), "sub", 10)); lay.addWidget(self.qty)
        self.note = _input(tr("supplies_note_ph")); lay.addWidget(self.note)
        self.log_economy_chk = QCheckBox(tr("supplies_restock_expense"))
        lay.addWidget(self.log_economy_chk)
        econ_row = QHBoxLayout()
        econ_row.addWidget(_lbl(tr("supplies_economy_amount"), "sub", 10))
        self.econ_amount = _input("0"); econ_row.addWidget(self.econ_amount)
        econ_row.addWidget(_lbl(tr("supplies_economy_category"), "sub", 10))
        self.econ_cat = QComboBox(); self.econ_cat.setEditable(True)
        self.econ_cat.addItem(item.get("economy_category") or "Supplies")
        econ_row.addWidget(self.econ_cat, 1)
        lay.addLayout(econ_row)
        lay.addWidget(_btn(tr("btn_save"), "solid", self.accept, 36))

    @staticmethod
    def _fmt(v):
        return str(int(v)) if float(v) == int(v) else str(v)

    def values(self):
        try:
            qty = float((self.qty.text() or "0").replace(",", "."))
        except ValueError:
            qty = 0.0
        try:
            amount = float((self.econ_amount.text() or "0").replace(",", "."))
        except ValueError:
            amount = 0.0
        return {"kind": self.kind.currentData(), "qty": qty, "note": self.note.text().strip(),
                "log_economy": self.log_economy_chk.isChecked(), "amount": amount,
                "category": self.econ_cat.currentText().strip()}


class SuppliesPage(QWidget):
    """Manajemen stok modern (kartu, bukan spreadsheet) + terhubung ke Economy."""

    def __init__(self, user_id):
        super().__init__(); self.user_id = user_id
        self._items = []
        self._selected_item_id = None
        self.setObjectName("suppliesPage")
        root = QVBoxLayout(self); root.setContentsMargins(22, 18, 22, 14); root.setSpacing(12)

        # ── Header ──
        header = _page_header("supplies")
        self.open_econ_btn = _btn(tr("supplies_open_economy"), "diamond", self._open_economy, 34)
        header.add_action(self.open_econ_btn)
        self.add_btn = _btn(tr("supplies_add"), "solid", self._add_item, 34)
