        lay = QVBoxLayout(dialog); form = QFormLayout(); name = QLineEdit(); day = QDateEdit(); day.setCalendarPopup(True); day.setDate(QDate.currentDate())
        category = QComboBox(); category.addItems([tr("love_category_date"), tr("love_category_milestone"), tr("love_category_gift"), tr("love_category_dream")])
        notes = QTextEdit(); notes.setMaximumHeight(90)
        form.addRow(tr("love_title_label"), name); form.addRow(tr("love_date_label"), day)
