    def load(self):
        self.profile_btn.setText(tr("love_edit_profile"))
        for index, key in enumerate(("love_tab_overview", "love_tab_connection", "love_tab_cycle",
                                     "love_tab_memories", "love_tab_gallery", "love_tab_plans")):
            self.tabs.setTabText(index, tr(key))
        for index, key in enumerate(("love_prompt_all", "love_prompt_connection", "love_prompt_appreciation",
                                     "love_prompt_support", "love_prompt_future", "love_prompt_fun",
                                     "love_prompt_favorites")):
            self.prompt_category_combo.setItemText(index, tr(key))
        for index, key in enumerate(("love_gallery_all", "love_gallery_shared", "love_gallery_private")):
            self.gallery_filter.setItemText(index, tr(key))
        self.profile=db.get_relationship_profile(self.user_id); self.health_profile=db.get_user_bmi_settings(self.user_id)
        self.couple_context=db.get_couple_context(self.user_id)
        relationship=self.couple_context.get("relationship") or {};read_only_grace=bool(relationship.get("read_only_grace"))
        self.end_couple_btn.setVisible(relationship.get("status")=="accepted" and not read_only_grace);self.tracking_btn.setVisible(relationship.get("status")=="accepted");self.profile_btn.setEnabled(not read_only_grace)
        own_user = self.couple_context.get("user") or db.get_user(self.user_id)
        official_partner = self.couple_context.get("partner")
        partner = (official_partner.get("display_name") if official_partner else None) or self.profile.get("partner_name") or tr("love_partner_not_set")
        _set_user_photo(self.my_love_photo, own_user, 58)
        partner_identity = official_partner or {"avatar_emoji": "♥", "avatar_color": "#b64f7a"}
        _set_user_photo(self.partner_love_photo, partner_identity, 58)
        couple_status=(tr("love_couple_linked",username=official_partner.get("username",""))
                       if official_partner else tr("love_couple_not_linked"))
